screenPanels.initJs:
function(container, apiUrl, tables) {
  // テーブルインデックス（重複受注検出結果テーブル）
  const DUPLICATE_TABLE_IDX = 0;
  const CHANNEL_TABLE_IDX = 1;
  const CONTRADICTION_TABLE_IDX = 2;

  let allDuplicates = [];
  let selectedDuplicate = null;

  // 1. 再描画関数
  function renderDuplicateRows(rows) {
    const tbody = container.querySelector("#duplicate-tbody");
    const countEl = container.querySelector("#result-count");

    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid rgba(0,0,0,0.1);"><td colspan="8" style="padding: 24px; text-align: center; color: var(--text-muted); font-size: 12px;">重複受注が検出されていません</td></tr>';
      countEl.textContent = "0件";
      return;
    }

    countEl.textContent = rows.length + "件";
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検出ステータス === "未確認" ? "#ff9800" : 
                          r.検出ステータス === "確認済み" ? "#4caf50" :
                          r.検出ステータス === "統合済み" ? "#2196f3" : "#9e9e9e";

      return `<tr style="border-bottom: 1px solid rgba(0,0,0,0.1); hover: background: rgba(0,0,0,0.05);">
        <td style="padding: 8px 12px; color: var(--text); font-weight: 500;">${r.主受注ID || "-"}</td>
        <td style="padding: 8px 12px; color: var(--text);">${r.顧客名 || "-"}</td>
        <td style="padding: 8px 12px; color: var(--text); font-size: 12px;">${r.受注日時 ? new Date(r.受注日時).toLocaleString("ja-JP") : "-"}</td>
        <td style="padding: 8px 12px; color: var(--text);">${r.チャネル名 || "-"}</td>
        <td style="padding: 8px 12px; text-align: right; color: var(--text);">¥${(r.金額 || 0).toLocaleString()}</td>
        <td style="padding: 8px 12px; text-align: center;">
          <span style="display: inline-block; padding: 2px 8px; background: rgba(255,152,0,0.15); color: #ff9800; border-radius: 3px; font-size: 12px; font-weight: 600;">${r.マッチング信頼度 || 0}%</span>
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <span style="display: inline-block; padding: 2px 8px; background: rgba(${statusColor === "#ff9800" ? "255,152,0" : statusColor === "#4caf50" ? "76,175,80" : statusColor === "#2196f3" ? "33,150,243" : "158,158,158"},0.15); color: ${statusColor}; border-radius: 3px; font-size: 11px; font-weight: 600;">${r.検出ステータス || "未確認"}</span>
        </td>
        <td style="padding: 8px 12px; text-align: center;">
          <button class="action-btn secondary compare-btn" data-id="${r.重複受注検出結果ID}" style="padding: 4px 10px; font-size: 12px;">比較</button>
        </td>
      </tr>`;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(DUPLICATE_TABLE_IDX);
    if (rows) {
      allDuplicates = rows;
      renderDuplicateRows(rows);
    }
  }

  // 3. 検索ボタン
  container.querySelector("#btn-search").addEventListener("click", async () => {
    const orderId = container.querySelector("#filter-order-id").value.trim();
    const customerName = container.querySelector("#filter-customer-name").value.trim();
    const scoreRange = container.querySelector("#filter-score-range").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allDuplicates;

    if (orderId) {
      filtered = filtered.filter(r => (r.主受注ID || "").includes(orderId) || (r.副受注ID || "").includes(orderId));
    }
    if (customerName) {
      filtered = filtered.filter(r => (r.顧客名 || "").includes(customerName));
    }
    if (scoreRange) {
      const [min, max] = scoreRange.split("-").map(Number);
      filtered = filtered.filter(r => {
        const score = r.マッチング信頼度 || 0;
        return score >= min && score <= max;
      });
    }
    if (status) {
      filtered = filtered.filter(r => r.検出ステータス === status);
    }

    renderDuplicateRows(filtered);
  });

  // 4. 比較ボタン（イベントデリゲーション）
  container.addEventListener("click", async e => {
    const compareBtn = e.target.closest(".compare-btn");
    if (compareBtn) {
      const duplicateId = compareBtn.dataset.id;
      selectedDuplicate = allDuplicates.find(d => d.重複受注検出結果ID === duplicateId);

      if (selectedDuplicate) {
        // 比較パネルに情報を設定
        container.querySelector("#comp-primary-id").textContent = selectedDuplicate.主受注ID || "-";
        container.querySelector("#comp-primary-customer").textContent = selectedDuplicate.顧客名 || "-";
        container.querySelector("#comp-primary-date").textContent = selectedDuplicate.受注日時 ? new Date(selectedDuplicate.受注日時).toLocaleString("ja-JP") : "-";
        container.querySelector("#comp-primary-channel").textContent = selectedDuplicate.チャネル名 || "-";
        container.querySelector("#comp-primary-amount").textContent = "¥" + (selectedDuplicate.金額 || 0).toLocaleString();
        container.querySelector("#comp-primary-score").textContent = (selectedDuplicate.マッチング信頼度 || 0) + "%";

        container.querySelector("#comp-secondary-id").textContent = selectedDuplicate.副受注ID || "-";
        container.querySelector("#comp-secondary-customer").textContent = selectedDuplicate.副顧客名 || selectedDuplicate.顧客名 || "-";
        container.querySelector("#comp-secondary-date").textContent = selectedDuplicate.副受注日時 ? new Date(selectedDuplicate.副受注日時).toLocaleString("ja-JP") : "-";
        container.querySelector("#comp-secondary-channel").textContent = selectedDuplicate.副チャネル名 || selectedDuplicate.チャネル名 || "-";
        container.querySelector("#comp-secondary-amount").textContent = "¥" + (selectedDuplicate.副金額 || selectedDuplicate.金額 || 0).toLocaleString();
        container.querySelector("#comp-secondary-score").textContent = (selectedDuplicate.副信頼度 || selectedDuplicate.マッチング信頼度 || 0) + "%";

        container.querySelector("#comp-confidence").textContent = (selectedDuplicate.マッチング信頼度 || 0) + "%";
        container.querySelector("#comp-reason").textContent = selectedDuplicate.マッチング理由 || "顧客名・金額・日時が一致";

        // 矛盾内容を表示
        const diffEl = container.querySelector("#comparison-differences");
        const diffs = [];
        if (selectedDuplicate.金額 !== selectedDuplicate.副金額) {
          diffs.push(`金額相違: ${selectedDuplicate.金額} vs ${selectedDuplicate.副金額}`);
        }
        if (selectedDuplicate.チャネル名 !== selectedDuplicate.副チャネル名) {
          diffs.push(`チャネル相違: ${selectedDuplicate.チャネル名} vs ${selectedDuplicate.副チャネル名}`);
        }
        if (!diffs.length) {
          diffs.push("矛盾なし（完全一致）");
        }
        diffEl.innerHTML = diffs.map(d => `<div>• ${d}</div>`).join("");

        // 対応方針をリセット
        container.querySelector("#comp-action").value = selectedDuplicate.対応方針 || "";
        container.querySelector("#comp-notes").value = selectedDuplicate.備考 || "";

        // モーダルを表示
        container.querySelector("#comparison-modal").removeAttribute("hidden");
      }
    }
  });

  // 5. 比較パネルのクローズ
  container.querySelector("#btn-close-comparison").addEventListener("click", () => {
    container.querySelector("#comparison-modal").setAttribute("hidden", "");
  });

  container.querySelector("#btn-cancel-comparison").addEventListener("click", () => {
    container.querySelector("#comparison-modal").setAttribute("hidden", "");
  });

  // 6. 比較結果の確認・保存
  container.querySelector("#btn-confirm-comparison").addEventListener("click", async () => {
    if (!selectedDuplicate) return;

    const action = container.querySelector("#comp-action").value;
    const notes = container.querySelector("#comp-notes").value;

    if (!action) {
      alert("対応方針を選択してください");
      return;
    }

    // 更新データを準備
    const updateData = {
      対応方針: action,
      備考: notes,
      検出ステータス: action === "統合" ? "統合済み" : action === "誤検出" ? "誤検出" : "確認済み",
      確認者ID: "current-user-id", // 実装時に現在ユーザーIDを取得
      確認日時: new Date().toISOString()
    };

    // API で更新
    const result = await window.aivicApi.update(DUPLICATE_TABLE_IDX, selectedDuplicate.重複受注検出結果ID, updateData);

    if (result) {
      alert("対応方針を保存しました");
      container.querySelector("#comparison-modal").setAttribute("hidden", "");

      // リスト再読み込み
      const rows = await window.aivicApi.list(DUPLICATE_TABLE_IDX);
      if (rows) {
        allDuplicates = rows;
        renderDuplicateRows(rows);
      }
    }
  });

  // 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const ocrTable = tables[0];
  const correctionTable = tables[1];
  const scoreTable = tables[2];

  let allOcrRecords = ocrTable?.records || [];
  let allScoreRecords = scoreTable?.records || [];
  let allCorrectionRecords = correctionTable?.records || [];
  let selectedOcrId = null;

  // ===== 1. 再描画関数 =====
  function renderOcrList(records) {
    const tbody = container.querySelector("#ocr-tbody");
    if (!records || records.length === 0) {
      tbody.innerHTML = '<tr style="background: var(--bg-main); color: var(--text-muted); text-align: center;"><td colspan="3" style="padding: 20px;">データなし</td></tr>';
      return;
    }

    tbody.innerHTML = records.map(r => {
      const score = allScoreRecords.find(s => s.order_id === r.order_id);
      const totalScore = score?.total_score || 0;
      const isLow = totalScore < 70;
      const warningFlag = score?.warning_flag ? '⚠' : '✓';
      const warningColor = isLow ? '#ff6a00' : '#4ade80';

      return `
        <tr data-id="${r.ocr_result_id}" style="cursor: pointer; background: var(--bg-main); border-bottom: 1px solid rgba(255,255,255,0.04); transition: background 0.2s;" onmouseover="this.style.background='rgba(255,255,255,0.08)'" onmouseout="this.style.background='var(--bg-main)'">
          <td style="padding: 8px 10px; color: var(--text);">${r.order_id?.substring(0, 8) || 'N/A'}</td>
          <td style="padding: 8px 10px; text-align: center; color: ${isLow ? '#ff6a00' : 'var(--primary)'}; font-weight: 600;">${totalScore}</td>
          <td style="padding: 8px 10px; text-align: center; color: ${warningColor}; font-size: 14px;">${warningFlag}</td>
        </tr>
      `;
    }).join("");

    // イベントデリゲーション：行クリックで詳細表示
    tbody.addEventListener("click", e => {
      const row = e.target.closest("tr");
      if (row) {
        const ocrId = row.dataset.id;
        selectedOcrId = ocrId;
        showDetail(ocrId);
        // 選択行をハイライト
        container.querySelectorAll("#ocr-tbody tr").forEach(r => r.style.background = "var(--bg-main)");
        row.style.background = "rgba(255,165,0,0.15)";
      }
    });
  }

  function showDetail(ocrId) {
    const detailPanel = container.querySelector("#detail-panel");
    const ocrRecord = allOcrRecords.find(r => r.ocr_result_id === ocrId);
    if (!ocrRecord) {
      detailPanel.innerHTML = '<div style="color: var(--text-muted); padding: 20px;">データが見つかりません</div>';
      return;
    }

    const scoreRecord = allScoreRecords.find(s => s.order_id === ocrRecord.order_id);
    const template = container.querySelector("#detail-form-template");
    const clone = template.content.cloneNode(true);

    // スコア表示
    if (scoreRecord) {
      clone.querySelector(".score-total").textContent = scoreRecord.total_score || 0;
      clone.querySelector(".score-completeness").textContent = scoreRecord.completeness_score || 0;
      clone.querySelector(".score-accuracy").textContent = scoreRecord.accuracy_score || 0;
      clone.querySelector(".score-consistency").textContent = scoreRecord.consistency_score || 0;
    }

    // 低信頼度項目リスト（検証結果から抽出）
    const lowConfidenceItems = container.querySelector("#low-confidence-items", clone);
    if (lowConfidenceItems) {
      const validationResults = tables[3]?.records || [];
      const relatedValidations = validationResults.filter(v => v.order_id === ocrRecord.order_id && v.severity !== 'low');

      if (relatedValidations.length > 0) {
        lowConfidenceItems.innerHTML = relatedValidations.map(v => `
          <div style="padding: 8px 10px; background: rgba(255,165,0,0.1); border-left: 3px solid #ff6a00; border-radius: 2px; font-size: 11px;">
            <div style="color: var(--text); font-weight: 600;">${v.validation_item}</div>
            <div style="color: var(--text-muted); margin-top: 2px;">重要度: ${v.severity}</div>
          </div>
        `).join("");
      } else {
        lowConfidenceItems.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">低信頼度項目なし</div>';
      }
    }

    // 修正履歴
    const historyDiv = clone.querySelector("#correction-history");
    if (historyDiv) {
      const corrections = allCorrectionRecords.filter(c => c.order_id === ocrRecord.order_id);
      if (corrections.length > 0) {
        historyDiv.innerHTML = corrections.map(c => `
          <div style="padding: 8px; background: rgba(74,222,128,0.1); border-left: 2px solid #4ade80; border-radius: 2px;">
            <div style="color: var(--text); font-size: 11px; font-weight: 600;">${c.field_name}</div>
            <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">理由: ${c.correction_reason}</div>
            <div style="color: var(--text-muted); font-size: 10px;">${new Date(c.correction_datetime).toLocaleString('ja-JP')}</div>
          </div>
        `).join("");
      } else {
        historyDiv.innerHTML = '<div style="color: var(--text-muted); font-size: 11px;">修正履歴なし</div>';
      }
    }

    detailPanel.innerHTML = "";
    detailPanel.appendChild(clone);

    // 修正確定ボタン
    const btnConfirm = detailPanel.querySelector(".btn-confirm-correction");
    if (btnConfirm) {
      btnConfirm.addEventListener("click", async () => {
        const fieldName = detailPanel.querySelector(".field-name").value;
        const fieldBefore = detailPanel.querySelector(".field-before").textContent;
        const fieldAfter = detailPanel.querySelector(".field-after").value;
        const reason = detailPanel.querySelector(".field-reason").value;
        const comment = detailPanel.querySelector(".field-comment").value;

        if (!fieldAfter.trim() || !reason) {
          alert("修正後の値と修正理由を入力してください");
          return;
        }

        const correctionData = {
          order_id: ocrRecord.order_id,
          field_name: fieldName,
          before_value: fieldBefore,
          after_value: fieldAfter,
          correction_reason: reason,
          correction_comment: comment,
          correction_datetime: new Date().toISOString(),
          user_id: "current-user"
        };

        const saved = await window.aivicApi.save(1, correctionData);
        if (saved) {
          alert("修正を確定しました");
          // 再度詳細を表示（履歴を更新）
          window.aivicApi.list(1).then(rows => {
            allCorrectionRecords = rows;
            showDetail(ocrId);
          });
          // KPI 更新
          updateKpis();
        }
      });
    }

    const btnCancel = detailPanel.querySelector(".btn-cancel-correction");
    if (btnCancel) {
      btnCancel.addEventListener("click", () => {
        detailPanel.querySelector(".field-after").value = "";
        detailPanel.querySelector(".field-reason").value = "";
        detailPanel.querySelector(".field-comment").value = "";
      });
    }
  }

  function updateKpis() {
    if (!allScoreRecords || allScoreRecords.length === 0) {
      container.querySelector('[data-testid="avg-score"]').textContent = "--";
      container.querySelector('[data-testid="low-confidence-count"]').textContent = "--";
      container.querySelector('[data-testid="corrected-count"]').textContent = "--";
      return;
    }

    const avgScore = Math.round(allScoreRecords.reduce((sum, s) => sum + (s.total_score || 0), 0) / allScoreRecords.length);
    const lowCount = allScoreRecords.filter(s => (s.total_score || 0) < 70).length;
    const correctedCount = allCorrectionRecords.length;

    container.querySelector('[data-testid="avg-score"]').textContent = avgScore;
    container.querySelector('[data-testid="low-confidence-count"]').textContent = lowCount;
    container.querySelector('[data-testid="corrected-count"]').textContent = correctedCount;
  }

  // ===== 2. 初期データ読み込み =====
  Promise.all([
    window.aivicApi.list(0),
    window.aivicApi.list(1),
    window.aivicApi.list(2)
  ]).then(([ocrRows, corrRows, scoreRows]) => {
    if (ocrRows) allOcrRecords = ocrRows;
    if (corrRows) allCorrectionRecords = corrRows;
    if (scoreRows) allScoreRecords = scoreRows;

    renderOcrList(allOcrRecords);
    updateKpis();
  });

  // ===== 3. 検索ボタン =====
  container.querySelector("#btn-search").addEventListener("click", () => {
    const orderId = container.querySelector("#input-order-id").value.trim();
    const scoreMin = parseInt(container.querySelector("#input-score-min").value) || 0;
    const scoreMax = parseInt(container.querySelector("#input-score-max").value) || 100;

    let filtered = allOcrRecords;

    if (orderId) {
      filtered = filtered.filter(r => r.order_id?.includes(orderId));
    }

    filtered = filtered.filter(r => {
      const score = allScoreRecords.find(s => s.order_id === r.order_id);
      const totalScore = score?.total_score || 0;
      return totalScore >= scoreMin && totalScore <= scoreMax;
    });

    renderOcrList(filtered);
  });

  // ===== 4. リセットボタン =====
  container.querySelector("#btn-reset").addEventListener("click", () => {
    container.querySelector("#input-order-id").value = "";
    container.querySelector("#input-score-min").value = "";
    container.querySelector("#input-score-max").value = "";
    renderOcrList(allOcrRecords);
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#priority-tbody");
  const modal = container.querySelector("#detail-modal");
  const detailCloseBtn = container.querySelector("#detail-close-btn");
  const detailSaveBtn = container.querySelector("#detail-save-btn");
  const detailEditBtn = container.querySelector("#detail-edit-button");
  const searchBtn = container.querySelector("[data-testid='search-button']");
  const exportBtn = container.querySelector("[data-testid='export-button']");
  const priorityFilter = container.querySelector("[data-testid='priority-filter']");
  const errorTypeFilter = container.querySelector("[data-testid='error-type-filter']");
  const statusFilter = container.querySelector("[data-testid='status-filter']");
  const confidenceMin = container.querySelector("[data-testid='confidence-min']");

  let allRows = [];
  let currentDetailId = null;

  // ステータスバッジ色
  function getStatusBadgeStyle(status) {
    const styles = {
      "未対応": "background: rgba(211,47,47,0.2); color: #ff6a6a;",
      "対応中": "background: rgba(255,215,0,0.2); color: #ffb300;",
      "完了": "background: rgba(76,175,80,0.2); color: #66bb6a;",
      "保留": "background: rgba(158,176,209,0.2); color: #9fb0d1;"
    };
    return styles[status] || "background: rgba(158,176,209,0.2); color: #9fb0d1;";
  }

  // 優先度バッジ色
  function getPriorityBadgeStyle(priority) {
    const p = parseInt(priority);
    if (p === 1) return "background: rgba(211,47,47,0.2); color: #ff6a6a; font-weight: 600;";
    if (p === 2) return "background: rgba(255,215,0,0.2); color: #ffb300; font-weight: 600;";
    if (p === 3) return "background: rgba(158,176,209,0.2); color: #9fb0d1;";
    return "background: rgba(100,100,100,0.2); color: #b0b0b0;";
  }

  // テーブル再描画
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="background: rgba(0,0,0,0.15); border-bottom: 1px solid rgba(255,255,255,0.08);"><td colspan="8" style="padding: 24px; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      updateStats([]);
      return;
    }

    // 優先度でソート（昇順 = 1が最初）
    rows.sort((a, b) => (parseInt(a.優先度レベル) || 999) - (parseInt(b.優先度レベル) || 999));

    tbody.innerHTML = rows.map((r, idx) => {
      const priorityLevel = r.優先度レベル || "-";
      const orderId = r.受注データID ? r.受注データID.substring(0, 8) : "-";
      const channel = r.チャネル || "-";
      const errorContent = r.エラー分類 || "-";
      const confidence = r.信頼度スコア || 0;
      const status = r.修正ステータス || "未対応";
      const detectedAt = r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : "-";

      return `
        <tr data-id="${r.優先度リストID}" style="background: ${idx % 2 === 0 ? 'rgba(0,0,0,0.08)' : 'transparent'}; border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;" onmouseover="this.style.background='rgba(255,215,0,0.1)'" onmouseout="this.style.background='${idx % 2 === 0 ? 'rgba(0,0,0,0.08)' : 'transparent'}'">
          <td style="padding: 8px; text-align: center;"><span style="${getPriorityBadgeStyle(priorityLevel)} padding: 4px 8px; border-radius: 3px; display: inline-block;">${priorityLevel}</span></td>
          <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 12px;">${orderId}</td>
          <td style="padding: 8px; color: var(--text);">${channel}</td>
          <td style="padding: 8px; color: var(--text); max-width: 300px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis;">${errorContent}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${confidence}%</td>
          <td style="padding: 8px;"><span style="${getStatusBadgeStyle(status)} padding: 4px 8px; border-radius: 3px; display: inline-block; font-size: 12px;">${status}</span></td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 12px;">${detectedAt}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="detail-btn" data-id="${r.優先度リストID}" style="padding: 4px 8px; background: var(--primary); color: #fff; border: none; border-radius: 3px; font-size: 11px; cursor: pointer;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");

    updateStats(rows);
  }

  // 統計更新
  function updateStats(rows) {
    const pending = rows.filter(r => r.修正ステータス === "未対応").length;
    const inprogress = rows.filter(r => r.修正ステータス === "対応中").length;
    const completed = rows.filter(r => r.修正ステータス === "完了").length;
    const total = rows.length;

    container.querySelector("#stat-pending").textContent = pending;
    container.querySelector("#stat-inprogress").textContent = inprogress;
    container.querySelector("#stat-completed").textContent = completed;
    container.querySelector("#stat-total").textContent = total;
  }

  // 初期データ読み込み
  async function loadData() {
    const rows = await window.aivicApi.list(0);
    allRows = rows || [];
    renderRows(allRows);
  }

  // 検索・フィルタ
  searchBtn.addEventListener("click", () => {
    const priority = priorityFilter.value;
    const errorType = errorTypeFilter.value;
    const status = statusFilter.value;
    const minConf = parseInt(confidenceMin.value) || 0;

    let filtered = allRows.filter(r => {
      if (priority && r.優先度レベル !== priority) return false;
      if (errorType && r.エラー分類 !== errorType) return false;
      if (status && r.修正ステータス !== status) return false;
      if (r.信頼度スコア < minConf) return false;
      return true;
    });

    renderRows(filtered);
  });

  // CSV出力
  exportBtn.addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("出力するデータがありません");
      return;
    }

    const headers = ["優先度", "受注ID", "チャネル", "エラー内容", "信頼度スコア", "ステータス", "検出日時"];
    const rows = allRows.map(r => [
      r.優先度レベル || "",
      r.受注データID ? r.受注データID.substring(0, 8) : "",
      r.チャネル || "",
      r.エラー分類 || "",
      r.信頼度スコア || "",
      r.修正ステータス || "",
      r.検出日時 ? new Date(r.検出日時).toLocaleString('ja-JP') : ""
    ]);

    const csv = "\uFEFF" + [headers, ...rows].map(row => 
      row.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(",")
    ).join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `priority-list-${new Date().toISOString().split('T')[0]}.csv`;
    link.click();
  });

  // 詳細モーダル表示
  container.addEventListener("click", async e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      const row = allRows.find(r => r.優先度リストID === id);
      if (!row) return;

      currentDetailId = id;
      container.querySelector("#detail-order-id").textContent = row.受注データID ? row.受注データID.substring(0, 8) : "-";
      container.querySelector("#detail-priority").textContent = row.優先度レベル || "-";
      container.querySelector("#detail-channel").textContent = row.チャネル || "-";
      container.querySelector("#detail-confidence").textContent = (row.信頼度スコア || 0) + "%";
      container.querySelector("#detail-error").textContent = row.エラー分類 || "-";
      container.querySelector("#detail-status").value = row.修正ステータス || "未対応";
      container.querySelector("#detail-notes").value = row.備考 || "";

      modal.removeAttribute("hidden");
    }
  });

  // モーダル閉じる
  detailCloseBtn.addEventListener("click", () => {
    modal.setAttribute("hidden", "");
    currentDetailId = null;
  });

  // 詳細保存
  detailSaveBtn.addEventListener("click", async () => {
    if (!currentDetailId) return;

    const status = container.querySelector("#detail-status").value;
    const notes = container.querySelector("#detail-notes").value;

    const updated = await window.aivicApi.update(0, currentDetailId, {
      修正ステータス: status,
      備考: notes,
      更新日時: new Date().toISOString()
    });

    if (updated) {
      await loadData();
      modal.setAttribute("hidden", "");
      currentDetailId = null;
    }
  });

  // 詳細編集ボタン（受注データ詳細確認・修正画面へ遷移）
  detailEditBtn.addEventListener("click", () => {
    if (!currentDetailId) return;
    const row = allRows.find(r => r.優先度リストID === currentDetailId);
    if (row && row.受注データID) {
      // 受注データ詳細確認・修正画面へ遷移
      window.showScreen("scr-1781413282852");
    }
  });

  // 初期ロード
  loadData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#result-tbody");
  const noResults = container.querySelector("#no-results");
  const scoreMinSlider = container.querySelector("#score-min-slider");
  const scoreMinDisplay = container.querySelector("#score-min-display");
  const scoreMinInput = container.querySelector("#score-min-input");
  const scoreMaxInput = container.querySelector("#score-max-input");
  const confidenceLevel = container.querySelector("#confidence-level");
  const orderIdSearch = container.querySelector("#order-id-search");
  const customerNameSearch = container.querySelector("#customer-name-search");
  const channelFilter = container.querySelector("#channel-filter");
  const validationStatus = container.querySelector("#validation-status");
  const correctionHistory = container.querySelector("#correction-history");
  const ocrConfidence = container.querySelector("#ocr-confidence");
  const duplicateDetection = container.querySelector("#duplicate-detection");
  const channelDiscrepancy = container.querySelector("#channel-discrepancy");
  const btnSearch = container.querySelector("#btn-search");
  const btnReset = container.querySelector("#btn-reset");
  const btnExport = container.querySelector("#btn-export");

  // 1. 再描画関数
  function renderRows(rows) {
    if (!rows || rows.length === 0) {
      tbody.innerHTML = "";
      noResults.style.display = "block";
      return;
    }
    noResults.style.display = "none";
    tbody.innerHTML = rows.map(r => {
      const scoreColor = r.総合スコア >= 80 ? "#4ade80" : r.総合スコア >= 50 ? "#fbbf24" : "#ef4444";
      const warningBadge = r.警告フラグ ? `<span style="background: #ef4444; color: #fff; padding: 2px 6px; border-radius: 3px; font-size: 11px;">警告</span>` : "-";
      return `
        <tr data-id="${r.id || ""}" style="border-bottom: 1px solid rgba(255,255,255,0.04); cursor: pointer;" onclick="window.showScreen('scr-1781413282852')">
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.受注ID || "-"}</td>
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.顧客名 || "-"}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid rgba(255,255,255,0.04); color: ${scoreColor}; font-weight: 600;">${r.総合スコア || 0}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.完全性スコア || 0}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.正確性スコア || 0}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.一貫性スコア || 0}</td>
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.チャネル || "-"}</td>
          <td style="padding: 8px; border-right: 1px solid rgba(255,255,255,0.04); color: var(--text);">${r.検証ステータス || "-"}</td>
          <td style="padding: 8px; text-align: center; border-right: 1px solid rgba(255,255,255,0.04);">${warningBadge}</td>
          <td style="padding: 8px; color: var(--text);">
            <button class="action-btn secondary detail-btn" data-id="${r.id || ""}" style="padding: 4px 8px; font-size: 12px;" onclick="event.stopPropagation(); window.showScreen('scr-1781413282852')">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ描画
  renderRows(tables[0]?.records || []);

  // 3. スライダーと入力フィールドの連動
  scoreMinSlider.addEventListener("input", (e) => {
    const val = parseInt(e.target.value);
    scoreMinDisplay.textContent = val;
    scoreMinInput.value = val;
  });

  scoreMinInput.addEventListener("change", (e) => {
    const val = Math.max(0, Math.min(100, parseInt(e.target.value) || 0));
    scoreMinSlider.value = val;
    scoreMinDisplay.textContent = val;
  });

  // 4. リセットボタン
  btnReset.addEventListener("click", () => {
    scoreMinSlider.value = 0;
    scoreMinDisplay.textContent = "0";
    scoreMinInput.value = 0;
    scoreMaxInput.value = 100;
    confidenceLevel.value = "";
    orderIdSearch.value = "";
    customerNameSearch.value = "";
    channelFilter.value = "";
    validationStatus.value = "";
    correctionHistory.value = "";
    ocrConfidence.value = "";
    duplicateDetection.value = "";
    channelDiscrepancy.value = "";
    renderRows(tables[0]?.records || []);
  });

  // 5. 検索ボタン
  btnSearch.addEventListener("click", async () => {
    const rows = tables[0]?.records || [];
    const minScore = parseInt(scoreMinInput.value) || 0;
    const maxScore = parseInt(scoreMaxInput.value) || 100;
    const level = confidenceLevel.value;
    const orderId = orderIdSearch.value.toLowerCase();
    const customerName = customerNameSearch.value.toLowerCase();
    const channel = channelFilter.value;
    const status = validationStatus.value;
    const hasCorrection = correctionHistory.value;
    const ocr = ocrConfidence.value;
    const dup = duplicateDetection.value;
    const disc = channelDiscrepancy.value;

    const filtered = rows.filter(r => {
      const score = r.総合スコア || 0;
      if (score < minScore || score > maxScore) return false;

      if (level === "high" && score < 80) return false;
      if (level === "medium" && (score < 50 || score >= 80)) return false;
      if (level === "low" && score >= 50) return false;
      if (level === "warning" && !r.警告フラグ) return false;

      if (orderId && !(r.受注ID || "").toLowerCase().includes(orderId)) return false;
      if (customerName && !(r.顧客名 || "").toLowerCase().includes(customerName)) return false;
      if (channel && r.チャネル !== channel) return false;
      if (status && r.検証ステータス !== status) return false;
      if (hasCorrection === "有" && !r.修正履歴有) return false;
      if (hasCorrection === "無" && r.修正履歴有) return false;
      if (ocr === "high" && (r.AI_OCR信頼度 || 0) < 80) return false;
      if (ocr === "medium" && ((r.AI_OCR信頼度 || 0) < 50 || (r.AI_OCR信頼度 || 0) >= 80)) return false;
      if (ocr === "low" && (r.AI_OCR信頼度 || 0) >= 50) return false;
      if (ocr === "manual" && !r.手動レビュー必要) return false;
      if (dup && r.重複検出ステータス !== dup) return false;
      if (disc && r.チャネル間矛盾ステータス !== disc) return false;

      return true;
    });

    renderRows(filtered);
  });

  // 6. CSVエクスポート
  btnExport.addEventListener("click", () => {
    const rows = tables[0]?.records || [];
    if (rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注ID", "顧客名", "総合スコア", "完全性スコア", "正確性スコア", "一貫性スコア", "チャネル", "検証ステータス", "警告フラグ", "修正履歴有"];
    const csvContent = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...rows.map(r => [
        r.受注ID || "",
        r.顧客名 || "",
        r.総合スコア || 0,
        r.完全性スコア || 0,
        r.正確性スコア || 0,
        r.一貫性スコア || 0,
        r.チャネル || "",
        r.検証ステータス || "",
        r.警告フラグ ? "はい" : "いいえ",
        r.修正履歴有 ? "有" : "無"
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csvContent], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `信頼度スコア_${new Date().toISOString().slice(0, 10)}.csv`;
    link.click();
  });

  // 7. Enter キーで検索
  [scoreMinInput, scoreMaxInput, orderIdSearch, customerNameSearch].forEach(el => {
    el.addEventListener("keypress", (e) => {
      if (e.key === "Enter") btnSearch.click();
    });
  });
}

function(container, apiUrl, tables) {
  // ========== 1. 音声ガイダンス制御 ==========
  let isGuidancePlaying = false;
  const guidanceSteps = [
    "ステップ 1/5: 顧客名を確認してください",
    "ステップ 2/5: 受注金額を確認してください",
    "ステップ 3/5: 受注日を確認してください",
    "ステップ 4/5: 商品名を確認してください",
    "ステップ 5/5: 数量を確認してください"
  ];
  let currentGuidanceStep = 0;

  container.querySelector("#btn-play-guidance").addEventListener("click", () => {
    isGuidancePlaying = true;
    container.querySelector("#btn-play-guidance").style.opacity = "0.6";
    container.querySelector("#btn-pause-guidance").style.opacity = "1";
    // 実際の音声再生はここで実装（Web Audio API / HTMLAudioElement）
    console.log("音声ガイダンス再生:", guidanceSteps[currentGuidanceStep]);
  });

  container.querySelector("#btn-pause-guidance").addEventListener("click", () => {
    isGuidancePlaying = false;
    container.querySelector("#btn-play-guidance").style.opacity = "1";
    container.querySelector("#btn-pause-guidance").style.opacity = "0.6";
    console.log("音声ガイダンス一時停止");
  });

  // 音量スライダー
  container.querySelector("#volume-slider").addEventListener("input", (e) => {
    const vol = e.target.value;
    container.querySelector("#volume-display").textContent = vol;
  });

  // ========== 2. OCR読み込みシミュレーション ==========
  let ocrProgress = 0;
  const mockExtractedData = [
    { field: "顧客名", value: "株式会社ABC", confidence: 98 },
    { field: "受注金額", value: "¥150,000", confidence: 92 },
    { field: "受注日", value: "2025-01-15", confidence: 95 },
    { field: "商品名", value: "プリンタ用紙 A4 500枚", confidence: 78 },
    { field: "数量", value: "5", confidence: 85 }
  ];

  container.querySelector("#btn-start-ocr").addEventListener("click", async () => {
    ocrProgress = 0;
    container.querySelector("#btn-start-ocr").disabled = true;

    // プログレスバーアニメーション
    const progressInterval = setInterval(() => {
      ocrProgress += Math.random() * 25;
      if (ocrProgress > 100) ocrProgress = 100;

      container.querySelector("#ocr-progress-bar").style.width = ocrProgress + "%";
      container.querySelector("#ocr-progress-text").textContent = Math.floor(ocrProgress) + "%";

      if (ocrProgress >= 100) {
        clearInterval(progressInterval);
        container.querySelector("#btn-start-ocr").disabled = false;
        renderExtractedData();
        renderConfidenceScores();
        renderLowConfidenceItems();
      }
    }, 200);
  });

  // ========== 3. 抽出データ表示 ==========
  function renderExtractedData() {
    const container_data = container.querySelector("#extracted-data-container");
    container_data.innerHTML = mockExtractedData.map(item => {
      const confidenceColor = item.confidence >= 90 ? "var(--primary)" : 
                              item.confidence >= 75 ? "#ffb84d" : "#ff6b6b";
      return `
        <div style="padding: 8px; background: rgba(0,0,0,0.25); border-radius: 3px; border-left: 3px solid ${confidenceColor};">
          <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;">
            <span style="font-size: 11px; color: var(--text-muted);">${item.field}</span>
            <span style="font-size: 11px; color: ${confidenceColor}; font-weight: 500;">${item.confidence}%</span>
          </div>
          <div style="font-size: 13px; color: var(--text); font-weight: 500;">${item.value}</div>
        </div>
      `;
    }).join("");
  }

  // ========== 4. 信頼度スコア表示 ==========
  function renderConfidenceScores() {
    const avgConfidence = Math.round(mockExtractedData.reduce((a, b) => a + b.confidence, 0) / mockExtractedData.length);
    container.querySelector("#score-overall").textContent = avgConfidence + "%";

    let warningLevel = "低";
    if (avgConfidence >= 90) warningLevel = "なし";
    else if (avgConfidence >= 80) warningLevel = "中";

    container.querySelector("#score-warning").textContent = warningLevel;
  }

  // ========== 5. 低信頼度項目ハイライト ==========
  function renderLowConfidenceItems() {
    const lowItems = mockExtractedData.filter(item => item.confidence < 85);
    const container_low = container.querySelector("#low-confidence-items");

    if (lowItems.length === 0) {
      container_low.innerHTML = '<div style="padding: 6px 8px; background: rgba(107, 255, 107, 0.15); border-left: 3px solid #6bff6b; border-radius: 2px; font-size: 11px; color: var(--text);">✓ 低信頼度項目なし</div>';
    } else {
      container_low.innerHTML = lowItems.map(item => `
        <div style="padding: 6px 8px; background: rgba(255, 107, 107, 0.15); border-left: 3px solid #ff6b6b; border-radius: 2px; font-size: 11px; color: var(--text);">
          <strong>${item.field}</strong>: ${item.confidence}% (値: ${item.value})
        </div>
      `).join("");
    }
  }

  // ========== 6. 手動修正適用 ==========
  container.querySelector("#btn-apply-correction").addEventListener("click", () => {
    const field = container.querySelector("#correction-field").value;
    const value = container.querySelector("#correction-value").value;

    if (!field || !value) {
      alert("修正項目と修正値を入力してください");
      return;
    }

    // mockExtractedData を更新
    const idx = mockExtractedData.findIndex(d => d.field === 
      (field === "customer_name" ? "顧客名" :
       field === "order_amount" ? "受注金額" :
       field === "order_date" ? "受注日" :
       field === "product_name" ? "商品名" : "数量"));

    if (idx >= 0) {
      mockExtractedData[idx].value = value;
      mockExtractedData[idx].confidence = 100; // 手動修正は信頼度100%
      renderExtractedData();
      renderConfidenceScores();
      renderLowConfidenceItems();

      container.querySelector("#correction-field").value = "";
      container.querySelector("#correction-value").value = "";
      alert("修正を適用しました");
    }
  });

  // ========== 7. カメラ/スキャナボタン ==========
  container.querySelector("#btn-camera").addEventListener("click", () => {
    alert("カメラを起動します（実装例）");
    // 実際にはMediaDevices.getUserMedia() を使用
  });

  container.querySelector("#btn-scanner").addEventListener("click", () => {
    alert("スキャナを起動します（実装例）");
  });

  // ========== 8. フッター操作 ==========
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    if (confirm("処理をキャンセルしますか？")) {
      window.showScreen("scr-1781413262699"); // 受注データ検証ダッシュボードへ
    }
  });

  container.querySelector("#btn-confirm-and-next").addEventListener("click", async () => {
    // 抽出データを保存してから次画面へ
    const ocrResultData = {
      extracted_fields: JSON.stringify(mockExtractedData),
      overall_confidence: Math.round(mockExtractedData.reduce((a, b) => a + b.confidence, 0) / mockExtractedData.length),
      processing_status: "成功",
      requires_manual_review: mockExtractedData.some(d => d.confidence < 85)
    };

    // AI_OCR読み込み結果テーブルに保存（tableIndex=3 と仮定）
    const saved = await window.aivicApi.save(3, ocrResultData);
    if (saved) {
      alert("OCR読み込み結果を保存しました");
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面へ
    }
  });

  // ========== 9. 初期表示 ==========
  container.querySelector("#btn-play-guidance").style.opacity = "1";
  container.querySelector("#btn-pause-guidance").style.opacity = "0.6";
  container.querySelector("#guidance-step-display").textContent = guidanceSteps[0];
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const VALIDATION_RESULT_IDX = 0;
  const CORRECTION_HISTORY_IDX = 1;
  const TRUST_SCORE_IDX = 2;
  const DUPLICATE_DETECTION_IDX = 3;
  const CHANNEL_CONFLICT_IDX = 4;
  const MISSING_INPUT_IDX = 5;

  let currentSelectedError = null;
  let correctionData = {};

  // ===== 1. エラー一覧を描画 =====
  function renderErrorList(errors) {
    const errorList = container.querySelector("#error-list");
    if (!errors || errors.length === 0) {
      errorList.innerHTML = '<div style="padding: 1rem; color: var(--text-muted); text-align: center; font-size: 0.8rem;">エラーなし</div>';
      return;
    }

    // 重要度でソート（致命的 > 高 > 中 > 低）
    const severityOrder = { "致命的": 0, "高": 1, "中": 2, "低": 3 };
    errors.sort((a, b) => (severityOrder[a.重要度] || 99) - (severityOrder[b.重要度] || 99));

    errorList.innerHTML = errors.map((err, idx) => {
      const severityColor = {
        "致命的": "#d32f2f",
        "高": "#ff6a00",
        "中": "#ffa500",
        "低": "#4caf50"
      }[err.重要度] || "#999";

      return `
        <div class="error-item" data-id="${err.検証結果ID || idx}" style="
          padding: 0.75rem;
          border-bottom: 1px solid rgba(255,255,255,0.08);
          cursor: pointer;
          transition: background 0.2s;
          background: ${currentSelectedError === (err.検証結果ID || idx) ? 'rgba(255,165,0,0.1)' : 'transparent'};
        " data-testid="error-item-${idx}">
          <div style="display: flex; align-items: flex-start; gap: 0.5rem;">
            <div style="
              width: 4px;
              height: 4px;
              border-radius: 50%;
              background: ${severityColor};
              margin-top: 0.35rem;
              flex-shrink: 0;
            "></div>
            <div style="flex: 1; min-width: 0;">
              <div style="font-size: 0.75rem; font-weight: 600; color: var(--text); word-break: break-word;">
                ${err.検証項目 || "不明"}
              </div>
              <div style="font-size: 0.7rem; color: var(--text-muted); margin-top: 0.2rem;">
                ${err.エラーコード || ""}
              </div>
              <div style="font-size: 0.65rem; color: ${severityColor}; margin-top: 0.15rem; font-weight: 600;">
                ${err.重要度 || ""}
              </div>
            </div>
          </div>
        </div>
      `;
    }).join("");

    // イベントデリゲーション：エラー選択
    container.querySelectorAll(".error-item").forEach(item => {
      item.addEventListener("click", () => {
        const errorId = item.dataset.id;
        currentSelectedError = errorId;
        const selectedError = errors.find(e => (e.検証結果ID || errors.indexOf(e)) == errorId);
        renderDetailPanel(selectedError);
        renderErrorList(errors); // 選択状態を反映
      });
    });
  }

  // ===== 2. 詳細修正フォームを描画 =====
  function renderDetailPanel(error) {
    const detailPanel = container.querySelector("#detail-panel");
    if (!error) {
