  // ===== 4. 修正履歴の折りたたみ制御 =====
  const toggleHistory = container.querySelector("#toggle-history");
  const historyPanel = container.querySelector("#history-panel");
  const toggleIcon = container.querySelector("#history-toggle-icon");
  let historyExpanded = true;

  toggleHistory.addEventListener("click", () => {
    historyExpanded = !historyExpanded;
    historyPanel.style.display = historyExpanded ? "block" : "none";
    toggleIcon.textContent = historyExpanded ? "▼" : "▶";
  });

  // ===== 5. 保存ボタン =====
  container.querySelector("[data-testid='save-button']").addEventListener("click", async () => {
    if (!currentSelectedError) {
      alert("修正するエラーを選択してください");
      return;
