    alert("修正内容を保存しました");
  });

  // ===== 6. 承認・確定ボタン =====
  container.querySelector("[data-testid='approve-button']").addEventListener("click", async () => {
    if (!confirm("この受注データを承認・確定しますか？")) return;
    alert("受注データを承認・確定しました。基幹システムへ連携します。");
    // 実際には連携承認フロー画面へ遷移
    window.showScreen("scr-1781413369295");
  });

  // ===== 7. キャンセルボタン =====
  container.querySelector("[data-testid='cancel-button']").addEventListener("click", () => {
    window.showScreen("scr-1781413262699"); // ダッシュボードへ戻る
  });

  // ===== 8. 初期化：エラー一覧を読み込んで描画 =====
  const validationResults = tables[VALIDATION_RESULT_IDX]?.records || [];
  renderErrorList(validationResults);
  renderHistoryTimeline();
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const CORRECTION_HISTORY_IDX = 1; // 受注データ修正履歴
  const VALIDATION_RESULT_IDX = 0;  // 受注データ検証結果
  const TRUST_SCORE_IDX = 2;        // 信頼度スコア
  const APPROVAL_FLOW_IDX = 3;      // 連携承認フロー

  // サンプル修正対象データ（実際には URL パラメータから取得）
  let currentCorrectionId = null;
  let currentOrderId = null;
  let beforeData = {};
  let afterData = {};

  // 修正履歴を時系列で描画
  function renderHistoryTimeline(histories) {
    const timeline = container.querySelector("#history-timeline");
    if (!histories || histories.length === 0) {
      timeline.innerHTML = '<div style="padding: 12px; color: var(--text-muted); text-align: center; font-size: 12px;">修正履歴がありません</div>';
      return;
    }
    timeline.innerHTML = histories
      .sort((a, b) => new Date(b.修正日時) - new Date(a.修正日時))
      .map((h, idx) => {
        const date = new Date(h.修正日時).toLocaleString('ja-JP');
        const isLatest = idx === 0;
        return `
          <div style="display: flex; gap: 10px; position: relative;">
            <div style="width: 24px; display: flex; justify-content: center; flex-shrink: 0;">
              <div style="width: 8px; height: 8px; border-radius: 50%; background: ${isLatest ? 'var(--primary)' : 'rgba(255,255,255,0.3)'}; margin-top: 6px;"></div>
              ${idx < histories.length - 1 ? '<div style="position: absolute; top: 16px; left: 11px; width: 2px; height: 32px; background: rgba(255,255,255,0.15);"></div>' : ''}
            </div>
            <div style="flex: 1; padding: 8px; background: rgba(0,0,0,0.15); border-radius: 3px; font-size: 11px;">
              <div style="color: var(--text); font-weight: 600; margin-bottom: 2px;">${h.修正項目名}</div>
              <div style="color: var(--text-muted); margin-bottom: 4px;">${date}</div>
              <div style="color: var(--text); font-size: 10px; margin-bottom: 2px;"><strong>理由:</strong> ${h.修正理由}</div>
              <div style="color: var(--text); font-size: 10px; margin-bottom: 2px;"><strong>修正者:</strong> ${h.修正ユーザーID}</div>
              <div style="color: var(--text-muted); font-size: 10px; margin-top: 4px; padding-top: 4px; border-top: 1px solid rgba(255,255,255,0.1);">
                ${h.修正前値} → ${h.修正後値}
              </div>
            </div>
          </div>
        `;
      }).join("");
  }

  // 修正項目一覧を描画
  function renderCorrectionItems(histories) {
    const tbody = container.querySelector("#correction-items-tbody");
    if (!histories || histories.length === 0) {
      tbody.innerHTML = '<tr><td colspan="3" style="padding: 12px; text-align: center; color: var(--text-muted);">修正項目がありません</td></tr>';
      return;
    }
    tbody.innerHTML = histories.map(h => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 8px; color: var(--text);">${h.修正項目名}</td>
        <td style="padding: 8px; color: var(--text-muted); font-size: 11px; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${h.修正前値}</td>
        <td style="padding: 8px; color: var(--text); font-size: 11px; max-width: 120px; overflow: hidden; text-overflow: ellipsis; white-space: nowrap;">${h.修正後値}</td>
      </tr>
    `).join("");
  }

  // 修正前後データを表示
  function renderDataComparison(histories) {
    const beforeDiv = container.querySelector("#before-data");
    const afterDiv = container.querySelector("#after-data");

    if (!histories || histories.length === 0) {
      beforeDiv.textContent = "(修正前データなし)";
      afterDiv.textContent = "(修正後データなし)";
      return;
    }

    // 最新の修正から修正前後を構築
    const before = {};
    const after = {};
    histories.forEach(h => {
      before[h.修正項目名] = h.修正前値;
      after[h.修正項目名] = h.修正後値;
    });

    beforeDiv.textContent = Object.entries(before)
      .map(([k, v]) => `${k}: ${v}`)
      .join("\n");
    afterDiv.textContent = Object.entries(after)
      .map(([k, v]) => `${k}: ${v}`)
      .join("\n");
  }

  // 信頼度スコアを表示
  function renderTrustScores(validationId) {
    if (!validationId) {
      container.querySelector("#score-before").textContent = "-";
      container.querySelector("#score-after").textContent = "-";
      container.querySelector("#score-breakdown").textContent = "完全性: - / 正確性: - / 一貫性: -";
      return;
    }
    // 実装: API から信頼度スコアを取得
    const scores = tables[TRUST_SCORE_IDX]?.records || [];
    const score = scores.find(s => s.検証結果ID === validationId);
    if (score) {
      container.querySelector("#score-before").textContent = Math.max(0, score.総合スコア - 15) + "";
      container.querySelector("#score-after").textContent = score.総合スコア + "";
      container.querySelector("#score-breakdown").textContent = 
        `完全性: ${score.完全性スコア} / 正確性: ${score.正確性スコア} / 一貫性: ${score.一貫性スコア}`;
    }
  }

  // 承認フロー状態を表示
  function renderApprovalFlow(orderId) {
    const flowDiv = container.querySelector("#approval-flow-status");
    const flows = tables[APPROVAL_FLOW_IDX]?.records || [];
    const flow = flows.find(f => f.受注データ_ID === orderId);
    if (!flow) {
      flowDiv.innerHTML = '<div style="padding: 8px; background: rgba(0,0,0,0.15); border-radius: 3px; color: var(--text-muted); font-size: 12px;">承認フロー情報がありません</div>';
      return;
    }
    const statusColor = flow.現在ステータス === "承認済" ? "#4ade80" : flow.現在ステータス === "却下" ? "#ff6a6a" : "var(--primary)";
    flowDiv.innerHTML = `
      <div style="padding: 8px; background: rgba(0,0,0,0.15); border-radius: 3px;">
        <div style="display: flex; justify-content: space-between; margin-bottom: 6px;">
          <span style="color: var(--text-muted); font-size: 11px;">段階</span>
          <span style="color: var(--text); font-weight: 600; font-size: 12px;">${flow.フロー段階}</span>
        </div>
        <div style="display: flex; justify-content: space-between; margin-bottom: 6px;">
          <span style="color: var(--text-muted); font-size: 11px;">ステータス</span>
          <span style="color: ${statusColor}; font-weight: 600; font-size: 12px;">${flow.現在ステータス}</span>
        </div>
        <div style="display: flex; justify-content: space-between;">
          <span style="color: var(--text-muted); font-size: 11px;">承認者</span>
          <span style="color: var(--text); font-size: 12px;">${flow.承認者_ID || "-"}</span>
        </div>
      </div>
    `;
  }

  // 初期化: 修正履歴を読み込んで表示
  async function initCorrectionScreen() {
    // URL パラメータから修正対象 ID を取得（デモでは最初のレコードを使用）
    const histories = tables[CORRECTION_HISTORY_IDX]?.records || [];
    if (histories.length === 0) {
      container.querySelector("#correction-id").textContent = "N/A";
      return;
    }

    const latestHistory = histories[0];
    currentOrderId = latestHistory.受注データID;
    currentCorrectionId = latestHistory.修正履歴ID;

    // 修正対象情報を表示
    container.querySelector("#correction-id").textContent = currentCorrectionId.substring(0, 8);
    container.querySelector("#order-id").textContent = currentOrderId.substring(0, 8);
    container.querySelector("#corrector-name").textContent = latestHistory.修正ユーザーID.substring(0, 8);
    container.querySelector("#correction-datetime").textContent = new Date(latestHistory.修正日時).toLocaleString('ja-JP');

    // 修正項目一覧・比較・履歴を描画
    renderCorrectionItems(histories);
    renderDataComparison(histories);
    renderHistoryTimeline(histories);

    // 検証結果情報を表示
    const validationResults = tables[VALIDATION_RESULT_IDX]?.records || [];
    const validation = validationResults.find(v => v.受注データID === currentOrderId);
    if (validation) {
      container.querySelector("#validation-status").textContent = validation.検証ステータス;
      container.querySelector("#validation-severity").textContent = validation.重要度;
      container.querySelector("#validation-error-code").textContent = validation.エラーコード || "-";
      renderTrustScores(validation.検証結果ID);
    }

    // 承認フロー状態を表示
    renderApprovalFlow(currentOrderId);
  }

  // 修正を保存
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    const reason = container.querySelector("#correction-reason").value;
    const notes = container.querySelector("#correction-notes").value;

    if (!reason) {
      alert("修正理由を選択してください");
      return;
    }

    // 新しい修正履歴レコードを保存
    const newCorrection = {
      修正履歴ID: "uuid-" + Date.now(),
      受注データID: currentOrderId,
      修正項目名: "複数項目",
      修正前値: JSON.stringify(beforeData),
      修正後値: JSON.stringify(afterData),
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
      検証結果ID: null,
      作成日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(CORRECTION_HISTORY_IDX, newCorrection);
    if (saved) {
      alert("修正内容を保存しました");
      // 화면 새로고침
      window.aivicApi.list(CORRECTION_HISTORY_IDX).then(histories => {
        renderCorrectionItems(histories);
        renderDataComparison(histories);
        renderHistoryTimeline(histories);
        container.querySelector("#correction-reason").value = "";
        container.querySelector("#correction-notes").value = "";
      });
    }
  });

  // キャンセルボタン
  container.querySelector("#btn-cancel").addEventListener("click", () => {
    window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面へ遷移
  });

  // 初期化実行
  initCorrectionScreen();
}

