      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = tables[DUPLICATE_DETECTION_TABLE]?.records || [];
    allDuplicates = rows;
    renderDuplicateList(rows);
  }

  // 3. 詳細ビューを開く
  async function openDetailView(duplicateId) {
    selectedDuplicate = allDuplicates.find(d => d.重複受注検出結果ID === duplicateId);
    if (!selectedDuplicate) return;

    // 信頼度スコア取得
    const scores = tables[CONFIDENCE_SCORE_TABLE]?.records || [];
    const scoreData = scores.find(s => s.受注データID === selectedDuplicate.主受注ID);

    // チャネル間矛盾取得
    const conflicts = tables[CHANNEL_CONFLICT_TABLE]?.records || [];
    const conflictData = conflicts.filter(c => 
      (c.受注ID_1 === selectedDuplicate.主受注ID && c.受注ID_2 === selectedDuplicate.副受注ID) ||
      (c.受注ID_1 === selectedDuplicate.副受注ID && c.受注ID_2 === selectedDuplicate.主受注ID)
    );

    // スコア表示
    container.querySelector("#score-matching").textContent = selectedDuplicate.マッチング信頼度 ? `${selectedDuplicate.マッチング信頼度}%` : '—';
    container.querySelector("#score-completeness").textContent = scoreData?.完全性スコア ? `${scoreData.完全性スコア}%` : '—';
    container.querySelector("#score-accuracy").textContent = scoreData?.正確性スコア ? `${scoreData.正確性スコア}%` : '—';
    container.querySelector("#score-consistency").textContent = scoreData?.一貫性スコア ? `${scoreData.一貫性スコア}%` : '—';

    // チャネル間矛盾表示
    const conflictHtml = conflictData.length > 0 
      ? conflictData.map(c => `<div>• ${c.矛盾タイプ}: ${c.矛盾内容}</div>`).join("")
      : '<div style="color: var(--text-muted);">矛盾なし</div>';
    container.querySelector("#channel-conflicts").innerHTML = conflictHtml;

    // 修正提案（ダミー）
    const suggestion = selectedDuplicate.マッチング信頼度 > 85 
      ? '高い信頼度で重複が確認されました。主受注に統合することを推奨します。'
      : selectedDuplicate.マッチング信頼度 > 60
      ? '中程度の信頼度です。詳細を確認してから判断してください。'
      : '低い信頼度です。誤検出の可能性があります。';
    container.querySelector("#correction-suggestion").innerHTML = `<div>${suggestion}</div>`;

    // 比較テーブル（ダミーデータ）
    const comparisonTbody = container.querySelector("#comparison-tbody");
    const comparisonItems = [
      { 項目: '受注日時', 主: '2024-01-15 10:30', 副: '2024-01-15 10:32', 一致: false },
      { 項目: '顧客名', 主: 'ABC株式会社', 副: 'ABC株式会社', 一致: true },
      { 項目: '受注金額', 主: '¥150,000', 副: '¥150,000', 一致: true },
      { 項目: '数量', 主: '10', 副: '10', 一致: true },
      { 項目: '配送先', 主: '東京都渋谷区', 副: '東京都渋谷区', 一致: true },
      { 項目: 'チャネル', 主: 'Web', 副: '電話', 一致: false },
    ];
    comparisonTbody.innerHTML = comparisonItems.map(item => `
      <tr style="border-bottom: 1px solid rgba(255,255,255,0.08);">
        <td style="padding: 6px 8px; color: var(--text-muted); font-weight: 500;">${item.項目}</td>
        <td style="padding: 6px 8px; color: var(--text);">${item.主}</td>
        <td style="padding: 6px 8px; color: var(--text);">${item.副}</td>
        <td style="padding: 6px 8px; text-align: center; color: ${item.一致 ? '#96ff96' : '#ff9999'}; font-weight: 600;">${item.一致 ? '✓' : '✗'}</td>
      </tr>
    `).join("");

    // 詳細ビュー表示
    container.querySelector("#detail-view").style.display = "block";
    container.querySelector("#detail-view").scrollIntoView({ behavior: "smooth", block: "nearest" });
  }

  // 4. 詳細ビューを閉じる
  function closeDetailView() {
    container.querySelector("#detail-view").style.display = "none";
    selectedDuplicate = null;
  }

  // 5. 修正を保存
  async function saveCorrection() {
    if (!selectedDuplicate) return;

    const policy = container.querySelector("#resolution-policy").value;
    const reason = container.querySelector("#correction-reason").value;
    const notes = container.querySelector("#correction-notes").value;

    if (!policy || !reason) {
      alert("対応方針と修正理由を選択してください");
      return;
    }

    // 修正履歴を保存
    const correctionData = {
      受注データID: selectedDuplicate.主受注ID,
      修正項目名: "重複受注対応",
      修正前値: selectedDuplicate.副受注ID,
      修正後値: policy === "統合" ? "統合済み" : policy,
      修正理由: reason,
      修正備考: notes,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString(),
    };

    const saved = await window.aivicApi.save(CORRECTION_HISTORY_TABLE, correctionData);
    if (saved) {
      alert("修正を保存しました");
      closeDetailView();
      // 重複検出結果のステータスを更新
      await window.aivicApi.update(DUPLICATE_DETECTION_TABLE, selectedDuplicate.重複受注検出結果ID, {
        検出ステータス: "確認済み",
        対応方針: policy,
      });
      loadInitialData();
    }
  }

  // 6. 検索・フィルター
  function applyFilters() {
    const keyword = container.querySelector("#search-keyword").value.toLowerCase();
    const scoreRange = container.querySelector("#filter-score").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allDuplicates.filter(d => {
      const matchKeyword = !keyword || 
        (d.主受注ID && d.主受注ID.toLowerCase().includes(keyword)) ||
        (d.副受注ID && d.副受注ID.toLowerCase().includes(keyword)) ||
        (d.顧客名 && d.顧客名.toLowerCase().includes(keyword));

      let matchScore = true;
      if (scoreRange) {
        const [min, max] = scoreRange.split("-").map(Number);
        matchScore = d.マッチング信頼度 >= min && d.マッチング信頼度 <= max;
      }

      const matchStatus = !status || d.検出ステータス === status;

      return matchKeyword && matchScore && matchStatus;
    });

    renderDuplicateList(filtered);
  }

  // 7. CSVエクスポート
  function exportToCSV() {
    const headers = ["主受注ID", "副受注ID", "顧客名", "重複度(%)", "マッチング理由", "ステータス", "対応方針"];
    const rows = allDuplicates.map(d => [
      d.主受注ID || "",
      d.副受注ID || "",
      d.顧客名 || "",
      d.マッチング信頼度 || 0,
      d.マッチング理由 || "",
      d.検出ステータス || "",
      d.対応方針 || "",
    ]);

    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => r.map(cell => `"${String(cell).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `duplicate-detection-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  }

  // イベントリスナー登録
  container.querySelector("#btn-search").addEventListener("click", applyFilters);
  container.querySelector("#btn-export").addEventListener("click", exportToCSV);
  container.querySelector("#btn-cancel-detail").addEventListener("click", closeDetailView);
  container.querySelector("#btn-save-correction").addEventListener("click", saveCorrection);

  // 詳細ボタンのイベントデリゲーション
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".view-detail-btn");
    if (detailBtn) {
      openDetailView(detailBtn.dataset.id);
    }
  });

  // 初期データ読み込み
  loadInitialData();
}

function(container, apiUrl, tables) {
  // テーブルインデックス（受注データ検証結果）
  const validationResultsIdx = 0;
  const trustScoreIdx = 1;
  const channelIdx = 2;

  // 集計データ保持
  let allValidationResults = [];
  let allTrustScores = [];
  let allChannels = [];
  let filteredResults = [];

  // ========== 1. 初期データ読み込み ==========
  async function loadInitialData() {
    try {
      const results = await window.aivicApi.list(validationResultsIdx);
      const scores = await window.aivicApi.list(trustScoreIdx);
      const channels = await window.aivicApi.list(channelIdx);

      allValidationResults = results || [];
      allTrustScores = scores || [];
      allChannels = channels || [];

      filteredResults = [...allValidationResults];
      updateDashboard();
    } catch (e) {
      console.error("Data load error:", e);
    }
  }

  // ========== 2. KPI 計算・更新 ==========
  function updateDashboard() {
    const kpiTotalOrders = container.querySelector('[data-testid="kpi-total-orders"]');
    const kpiErrorCount = container.querySelector('[data-testid="kpi-error-count"]');
    const kpiWarningCount = container.querySelector('[data-testid="kpi-warning-count"]');
    const kpiFixedCount = container.querySelector('[data-testid="kpi-fixed-count"]');
    const kpiPendingCount = container.querySelector('[data-testid="kpi-pending-count"]');
    const kpiAvgScore = container.querySelector('[data-testid="kpi-avg-score"]');

    // 総受注件数（ユニークな受注データID）
    const uniqueOrderIds = new Set(filteredResults.map(r => r.受注データID));
    const totalOrders = uniqueOrderIds.size;

    // ステータス別集計
    const errorCount = filteredResults.filter(r => r.検証ステータス === '不合格').length;
    const warningCount = filteredResults.filter(r => r.検証ステータス === '警告').length;
    const fixedCount = filteredResults.filter(r => r.対応状況 === '完了').length;
    const pendingCount = filteredResults.filter(r => r.対応状況 === '保留').length;

    // 平均信頼度スコア
    const avgScore = allTrustScores.length > 0
      ? Math.round(allTrustScores.reduce((sum, s) => sum + (s.総合スコア || 0), 0) / allTrustScores.length)
      : 0;

    kpiTotalOrders.textContent = totalOrders;
    kpiErrorCount.textContent = errorCount;
    kpiWarningCount.textContent = warningCount;
    kpiFixedCount.textContent = fixedCount;
    kpiPendingCount.textContent = pendingCount;
    kpiAvgScore.textContent = avgScore;

    // チャート更新
    updateChannelErrorChart();
    updateValidationPieChart();
    updateSummaryTable();
  }

  // ========== 3. チャネル別エラー率グラフ ==========
  function updateChannelErrorChart() {
    const canvas = container.querySelector('#chart-channel-error');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // チャネル別集計
    const channelStats = {};
    allChannels.forEach(ch => {
      channelStats[ch.チャネルコード] = { name: ch.チャネル名, total: 0, error: 0 };
    });

    filteredResults.forEach(r => {
      const chCode = r.チャネルコード || 'UNKNOWN';
      if (!channelStats[chCode]) {
        channelStats[chCode] = { name: chCode, total: 0, error: 0 };
      }
      channelStats[chCode].total++;
      if (r.検証ステータス === '不合格') {
        channelStats[chCode].error++;
      }
    });

    const labels = Object.keys(channelStats).map(k => channelStats[k].name);
    const errorRates = Object.keys(channelStats).map(k => {
      const stat = channelStats[k];
      return stat.total > 0 ? Math.round((stat.error / stat.total) * 100) : 0;
    });

    // 棒グラフ描画（Canvas）
    const barWidth = canvas.width / (labels.length + 1);
    const maxRate = Math.max(...errorRates, 100);
    const scale = (canvas.height - 40) / maxRate;

    ctx.fillStyle = '#9fb0d1';
    ctx.font = '11px sans-serif';
    ctx.textAlign = 'center';

    labels.forEach((label, i) => {
      const x = (i + 1) * barWidth;
      const rate = errorRates[i];
      const barHeight = rate * scale;
      const y = canvas.height - 30 - barHeight;

      // 棒
      ctx.fillStyle = rate > 50 ? '#ff6b6b' : rate > 20 ? '#ffb74d' : '#81c784';
      ctx.fillRect(x - barWidth * 0.3, y, barWidth * 0.6, barHeight);

      // ラベル
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(label, x, canvas.height - 8);
      ctx.fillText(rate + '%', x, y - 4);
    });
  }

  // ========== 4. 検証結果内訳円グラフ ==========
  function updateValidationPieChart() {
    const canvas = container.querySelector('#chart-validation-pie');
    if (!canvas) return;

    const ctx = canvas.getContext('2d');
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // ステータス別集計
    const statusCounts = {
      '合格': filteredResults.filter(r => r.検証ステータス === '合格').length,
      '不合格': filteredResults.filter(r => r.検証ステータス === '不合格').length,
      '警告': filteredResults.filter(r => r.検証ステータス === '警告').length,
      '保留': filteredResults.filter(r => r.検証ステータス === '保留').length
    };

    const total = Object.values(statusCounts).reduce((a, b) => a + b, 0);
    if (total === 0) {
      ctx.fillStyle = '#9fb0d1';
      ctx.font = '12px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText('データなし', canvas.width / 2, canvas.height / 2);
      return;
    }

    const colors = {
      '合格': '#81c784',
      '不合格': '#ff6b6b',
      '警告': '#ffb74d',
      '保留': '#ba68c8'
    };

    const centerX = canvas.width / 2;
    const centerY = canvas.height / 2;
    const radius = Math.min(canvas.width, canvas.height) / 2 - 20;

    let startAngle = 0;
    Object.entries(statusCounts).forEach(([status, count]) => {
      const sliceAngle = (count / total) * 2 * Math.PI;

      ctx.fillStyle = colors[status];
      ctx.beginPath();
      ctx.moveTo(centerX, centerY);
      ctx.arc(centerX, centerY, radius, startAngle, startAngle + sliceAngle);
      ctx.closePath();
      ctx.fill();

      // ラベル
      const labelAngle = startAngle + sliceAngle / 2;
      const labelX = centerX + Math.cos(labelAngle) * (radius * 0.6);
      const labelY = centerY + Math.sin(labelAngle) * (radius * 0.6);
      ctx.fillStyle = '#fff';
      ctx.font = 'bold 11px sans-serif';
      ctx.textAlign = 'center';
      ctx.fillText(Math.round((count / total) * 100) + '%', labelX, labelY);

      startAngle += sliceAngle;
    });

    // 凡例
    ctx.font = '10px sans-serif';
    ctx.textAlign = 'left';
    let legendY = 10;
    Object.entries(statusCounts).forEach(([status, count]) => {
      ctx.fillStyle = colors[status];
      ctx.fillRect(10, legendY, 10, 10);
      ctx.fillStyle = '#9fb0d1';
      ctx.fillText(status + ': ' + count, 25, legendY + 9);
      legendY += 16;
    });
  }

  // ========== 5. サマリーテーブル更新 ==========
  function updateSummaryTable() {
    const tbody = container.querySelector('#summary-tbody');

    // チャネル別集計
    const channelStats = {};
    allChannels.forEach(ch => {
      channelStats[ch.チャネルコード] = {
        name: ch.チャネル名,
        total: 0,
        error: 0,
        warning: 0,
        fixed: 0
      };
    });

    filteredResults.forEach(r => {
      const chCode = r.チャネルコード || 'UNKNOWN';
      if (!channelStats[chCode]) {
        channelStats[chCode] = { name: chCode, total: 0, error: 0, warning: 0, fixed: 0 };
      }
      channelStats[chCode].total++;
      if (r.検証ステータス === '不合格') channelStats[chCode].error++;
      if (r.検証ステータス === '警告') channelStats[chCode].warning++;
      if (r.対応状況 === '完了') channelStats[chCode].fixed++;
    });

    const rows = Object.keys(channelStats).map(chCode => {
      const stat = channelStats[chCode];
      const errorRate = stat.total > 0 ? Math.round((stat.error / stat.total) * 100) : 0;
      return `
        <tr style="border-bottom: 1px solid rgba(255,255,255,0.05);">
          <td style="padding: 8px; color: var(--text);">${stat.name}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${stat.total}</td>
          <td style="padding: 8px; text-align: center; color: #ff6b6b;">${stat.error}</td>
          <td style="padding: 8px; text-align: center; color: #ffb74d;">${stat.warning}</td>
          <td style="padding: 8px; text-align: center; color: #81c784;">${stat.fixed}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${errorRate}%</td>
        </tr>
      `;
    });

    tbody.innerHTML = rows.length > 0 ? rows.join('') : '<tr><td colspan="6" style="padding: 12px; text-align: center; color: var(--text-muted);">データなし</td></tr>';
  }

  // ========== 6. フィルタ適用 ==========
  function applyFilters() {
    const dateFrom = container.querySelector('#filter-date-from').value;
    const dateTo = container.querySelector('#filter-date-to').value;
    const channel = container.querySelector('#filter-channel').value;
    const user = container.querySelector('#filter-user').value;
    const status = container.querySelector('#filter-status').value;

    filteredResults = allValidationResults.filter(r => {
      const execDate = new Date(r.検証実行日時);
      if (dateFrom && execDate < new Date(dateFrom)) return false;
      if (dateTo && execDate > new Date(dateTo)) return false;
      if (channel && r.チャネルコード !== channel) return false;
      if (user && r.作成者ID !== user) return false;
      if (status && r.検証ステータス !== status) return false;
      return true;
    });

    updateDashboard();
  }

  // ========== 7. イベントリスナー ==========
  container.querySelector('#btn-search').addEventListener('click', applyFilters);

  container.querySelector('#btn-reset').addEventListener('click', () => {
    container.querySelector('#filter-date-from').value = '';
    container.querySelector('#filter-date-to').value = '';
    container.querySelector('#filter-channel').value = '';
    container.querySelector('#filter-user').value = '';
    container.querySelector('#filter-status').value = '';
    filteredResults = [...allValidationResults];
    updateDashboard();
  });

  container.querySelector('#btn-detail-dashboard').addEventListener('click', () => {
    window.showScreen('scr-1781413262699');
  });

  container.querySelector('#btn-detail-results').addEventListener('click', () => {
    window.showScreen('scr-1781413382983');
  });

  container.querySelector('#btn-export-csv').addEventListener('click', () => {
    const headers = ['チャネル', '受注件数', 'エラー', '警告', '修正完了', 'エラー率'];
    const channelStats = {};
    allChannels.forEach(ch => {
      channelStats[ch.チャネルコード] = {
        name: ch.チャネル名,
        total: 0,
        error: 0,
        warning: 0,
        fixed: 0
      };
    });

    filteredResults.forEach(r => {
      const chCode = r.チャネルコード || 'UNKNOWN';
      if (!channelStats[chCode]) {
        channelStats[chCode] = { name: chCode, total: 0, error: 0, warning: 0, fixed: 0 };
      }
      channelStats[chCode].total++;
      if (r.検証ステータス === '不合格') channelStats[chCode].error++;
      if (r.検証ステータス === '警告') channelStats[chCode].warning++;
      if (r.対応状況 === '完了') channelStats[chCode].fixed++;
    });

    const rows = Object.keys(channelStats).map(chCode => {
      const stat = channelStats[chCode];
      const errorRate = stat.total > 0 ? Math.round((stat.error / stat.total) * 100) : 0;
      return [stat.name, stat.total, stat.error, stat.warning, stat.fixed, errorRate + '%'];
    });

    const csv = '\uFEFF' + [headers, ...rows].map(r => r.map(c => `"${c}"`).join(',')).join('\n');
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8;' });
    const link = document.createElement('a');
    link.href = URL.createObjectURL(blob);
    link.download = 'aggregation-results.csv';
    link.click();
  });

  // ========== 8. 初期化実行 ==========
  loadInitialData();
}

function(container, apiUrl, tables) {
  const orderListTbody = container.querySelector("#order-list-tbody");
