    // 基本情報
    container.querySelector("#detail-order-id").textContent = order.受注ID || "-";
    container.querySelector("#detail-customer-name").textContent = order.顧客名 || "-";
    container.querySelector("#detail-amount").textContent = order.受注金額 ? "¥" + order.受注金額.toLocaleString() : "-";
    container.querySelector("#detail-channel").textContent = order.チャネル || "-";

    // 信頼度スコア
    container.querySelector("#detail-score-total").textContent = order.信頼度スコア || "-";
    container.querySelector("#detail-score-completeness").textContent = order.完全性スコア || "-";
    container.querySelector("#detail-score-accuracy").textContent = order.正確性スコア || "-";
    container.querySelector("#detail-score-consistency").textContent = order.一貫性スコア || "-";

    // 検証エラー
    const errorsHtml = order.検証エラー && order.検証エラー.length > 0
      ? order.検証エラー.map(e => `
          <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.06);">
            <div style="color: #ff6a00; font-weight: 600; margin-bottom: 2px;">● ${e.エラーコード}</div>
            <div style="color: var(--text-muted); font-size: 10px;">${e.エラーメッセージ}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 11px;">問題なし</div>';
    container.querySelector("#detail-errors").innerHTML = errorsHtml;

    // 入力漏れ
    const missingHtml = order.入力漏れ項目 && order.入力漏れ項目.length > 0
      ? order.入力漏れ項目.map(m => `
          <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.06);">
            <div style="color: #ffd700; font-weight: 600; margin-bottom: 2px;">● ${m.項目名}</div>
            <div style="color: var(--text-muted); font-size: 10px;">区分: ${m.区分}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 11px;">入力漏れなし</div>';
    container.querySelector("#detail-missing").innerHTML = missingHtml;

    // チャネル間矛盾
    const conflictsHtml = order.チャネル間矛盾 && order.チャネル間矛盾.length > 0
      ? order.チャネル間矛盾.map(c => `
          <div style="padding: 6px 0; border-bottom: 1px solid rgba(255,255,255,0.06);">
            <div style="color: #4a9eff; font-weight: 600; margin-bottom: 2px;">● ${c.矛盾タイプ}</div>
            <div style="color: var(--text-muted); font-size: 10px;">${c.矛盾内容}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 11px;">矛盾なし</div>';
    container.querySelector("#detail-channel-conflicts").innerHTML = conflictsHtml;

    // 承認フロー
    container.querySelector("#detail-flow-stage").textContent = order.フロー段階 || "-";
    container.querySelector("#detail-flow-status").textContent = order.フロー状態 || "-";

    // 承認履歴
    const historyHtml = order.承認履歴 && order.承認履歴.length > 0
      ? order.承認履歴.map((h, i) => `
          <div style="padding: 8px 0; border-bottom: 1px solid rgba(255,255,255,0.06); position: relative; padding-left: 20px;">
            <div style="position: absolute; left: 0; top: 10px; width: 8px; height: 8px; border-radius: 50%; background: var(--primary);"></div>
            <div style="color: var(--text); font-weight: 500; font-size: 11px; margin-bottom: 2px;">
              ${h.承認者} - ${h.判定結果}
            </div>
            <div style="color: var(--text-muted); font-size: 10px; margin-bottom: 2px;">${h.判定日時}</div>
            <div style="color: var(--text-muted); font-size: 10px;">${h.判定理由}</div>
          </div>
        `).join("")
      : '<div style="color: var(--text-muted); font-size: 11px;">履歴なし</div>';
    container.querySelector("#detail-history").innerHTML = historyHtml;

    // フォームをリセット
    approvalDecision.value = "";
    approvalReason.value = "";
  }

  // 3. 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    allOrders = rows || [];
    renderOrderList(allOrders);
  });

  // 4. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const row = e.target.closest(".order-row");
    if (row) {
      const orderId = row.dataset.id;
      const order = allOrders.find(o => o.id === orderId);
      if (order) {
        showDetail(order);
        // 選択行をハイライト
        container.querySelectorAll(".order-row").forEach(r => r.style.background = "");
        row.style.background = "rgba(255,215,0,0.08)";
      }
    }
  });

  // 5. 検索・フィルタ
  searchBtn.addEventListener("click", () => {
    const keyword = searchInput.value.toLowerCase();
    const status = statusFilter.value;
    const scoreRange = scoreFilter.value;

    let filtered = allOrders.filter(o => {
      const matchKeyword = !keyword || 
        (o.受注ID && o.受注ID.toLowerCase().includes(keyword)) ||
        (o.顧客名 && o.顧客名.toLowerCase().includes(keyword));

      const matchStatus = !status || o.検証ステータス === status;

      let matchScore = true;
      if (scoreRange) {
        const score = o.信頼度スコア || 0;
        if (scoreRange === "0-30") matchScore = score <= 30;
        else if (scoreRange === "31-60") matchScore = score > 30 && score <= 60;
        else if (scoreRange === "61-100") matchScore = score > 60;
      }

      return matchKeyword && matchStatus && matchScore;
    });

    renderOrderList(filtered);
  });

  // 6. 承認判定送信
  btnApprove.addEventListener("click", async () => {
    if (!selectedOrderId) {
      alert("受注を選択してください");
      return;
    }
    if (!approvalDecision.value) {
      alert("判定結果を選択してください");
      return;
    }

    const historyRecord = {
      受注データID: selectedOrderId,
      承認者ユーザーID: "current-user-id",
      判定結果: approvalDecision.value,
      判定理由: approvalReason.value,
      判定日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, historyRecord);
    if (saved) {
      alert("判定を送信しました");
      approvalDecision.value = "";
      approvalReason.value = "";
      // 一覧を再読み込み
      window.aivicApi.list(0).then(rows => {
        allOrders = rows || [];
        renderOrderList(allOrders);
      });
    }
  });

  // 7. キャンセル
  btnCancelApproval.addEventListener("click", () => {
    approvalDecision.value = "";
    approvalReason.value = "";
  });
}

