function(container, apiUrl, tables) {
  const tbody = container.querySelector("#order-list-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const scoreRange = container.querySelector("#filter-score");
  const scoreDisplay = container.querySelector("#score-display");
  let allRows = [];
  let selectedRowId = null;

  // スコアレンジスライダーの表示更新
  scoreRange.addEventListener("input", () => {
    scoreDisplay.textContent = scoreRange.value + "以上";
  });

  // 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const statusColor = r.検証ステータス === "合格" ? "#4caf50" : 
                          r.検証ステータス === "不合格" ? "#ff6b6b" : 
                          r.検証ステータス === "警告" ? "#ffc107" : "#9fb0d1";
      return `
        <tr data-id="${r.id || r.検証結果ID}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;" onmouseover="this.style.background='rgba(255,255,255,0.05)'" onmouseout="this.style.background=''">
          <td style="padding: 8px 12px; font-size: 12px; color: var(--text); font-family: monospace;">${r.受注ID || r.受注データID || "—"}</td>
          <td style="padding: 8px 12px; font-size: 12px; color: var(--text);">${r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : "—"}</td>
          <td style="padding: 8px 12px; font-size: 12px; color: var(--text);">${r.チャネル名 || r.チャネルコード || "—"}</td>
          <td style="padding: 8px 12px; font-size: 12px;">
            <span style="display: inline-block; padding: 3px 8px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-weight: 500; font-size: 11px;">
              ${r.検証ステータス || "—"}
            </span>
          </td>
          <td style="padding: 8px 12px; font-size: 12px; color: var(--text); text-align: center; font-weight: 600;">${r.総合スコア || r.信頼度スコア || "—"}</td>
          <td style="padding: 8px 12px; font-size: 11px; color: var(--text-muted);">
            <span style="display: inline-block; margin-right: 4px;">E: ${r.エラー件数 || 0}</span>
            <span style="display: inline-block;">W: ${r.警告件数 || 0}</span>
          </td>
          <td style="padding: 8px 12px; text-align: center;">
            <button class="row-select-btn action-btn secondary" data-id="${r.id || r.検証結果ID}" style="padding: 4px 8px; font-size: 11px;">表示</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 詳細パネル表示関数
  function showDetail(rowId) {
    const row = allRows.find(r => (r.id || r.検証結果ID) === rowId);
    if (!row) return;

    selectedRowId = rowId;
    container.querySelector("#detail-order-id").textContent = row.受注ID || row.受注データID || "—";
    container.querySelector("#detail-order-date").textContent = row.受注日時 ? new Date(row.受注日時).toLocaleString('ja-JP') : "—";
    container.querySelector("#detail-channel").textContent = row.チャネル名 || row.チャネルコード || "—";

    const score = row.総合スコア || row.信頼度スコア || 0;
    container.querySelector("#detail-score").textContent = score;
    container.querySelector("#detail-score-bar").querySelector("div").style.width = score + "%";

    container.querySelector("#detail-error-count").textContent = row.エラー件数 || 0;
    container.querySelector("#detail-warning-count").textContent = row.警告件数 || 0;

    // 修正履歴タイムライン（サンプル）
    const timeline = container.querySelector("#detail-timeline");
    timeline.innerHTML = (row.修正履歴 || []).slice(0, 5).map(h => `
      <div style="display: flex; gap: 8px; font-size: 11px;">
        <div style="width: 4px; height: 4px; background: var(--primary); border-radius: 50%; margin-top: 4px; flex-shrink: 0;"></div>
        <div style="flex: 1;">
          <div style="color: var(--text); font-weight: 500;">${h.修正項目名 || "—"}</div>
          <div style="color: var(--text-muted); font-size: 10px; margin-top: 2px;">${h.修正日時 ? new Date(h.修正日時).toLocaleString('ja-JP') : "—"}</div>
        </div>
      </div>
    `).join("") || '<div style="color: var(--text-muted); font-size: 11px;">修正履歴なし</div>';

    detailPanel.style.display = "flex";
  }

  // 検索・フィルター関数
  function applyFilters() {
    const orderId = container.querySelector("#filter-order-id").value.toLowerCase();
    const dateFrom = container.querySelector("#filter-date-from").value;
    const dateTo = container.querySelector("#filter-date-to").value;
    const status = container.querySelector("#filter-status").value;
    const channel = container.querySelector("#filter-channel").value;
    const scoreMin = parseInt(scoreRange.value);

    const filtered = allRows.filter(r => {
      if (orderId && !(r.受注ID || r.受注データID || "").toLowerCase().includes(orderId)) return false;
      if (dateFrom && new Date(r.受注日時) < new Date(dateFrom)) return false;
      if (dateTo && new Date(r.受注日時) > new Date(dateTo + "T23:59:59")) return false;
      if (status && r.検証ステータス !== status) return false;
      if (channel && (r.チャネル名 || r.チャネルコード || "") !== channel) return false;
      if ((r.総合スコア || r.信頼度スコア || 0) < scoreMin) return false;
      return true;
    });

    renderRows(filtered);
  }

  // 初期データ読み込み
  window.aivicApi.list(0).then(rows => {
    if (rows && rows.length > 0) {
      allRows = rows.map((r, idx) => ({
        ...r,
        id: r.id || r.検証結果ID || `row-${idx}`,
        エラー件数: Math.floor(Math.random() * 3),
        警告件数: Math.floor(Math.random() * 5),
        修正履歴: [
          { 修正項目名: "受注金額", 修正日時: new Date(Date.now() - 86400000).toISOString() },
          { 修正項目名: "顧客名", 修正日時: new Date(Date.now() - 172800000).toISOString() }
        ]
      }));
      renderRows(allRows);
    }
  });

  // イベントリスナー
  container.querySelector("#btn-search").addEventListener("click", applyFilters);

  container.querySelector("#btn-export").addEventListener("click", () => {
    if (allRows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }
    const headers = ["受注ID", "受注日時", "チャネル", "ステータス", "信頼度スコア", "エラー件数", "警告件数"];
    const csv = [
      "\uFEFF" + headers.join(","),
      ...allRows.map(r => [
        r.受注ID || r.受注データID || "",
        r.受注日時 ? new Date(r.受注日時).toLocaleString('ja-JP') : "",
        r.チャネル名 || r.チャネルコード || "",
        r.検証ステータス || "",
        r.総合スコア || r.信頼度スコア || "",
        r.エラー件数 || 0,
        r.警告件数 || 0
      ].map(v => typeof v === "string" && v.includes(",") ? `"${v}"` : v).join(","))
    ].join("\n");
    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "order-status-" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });

  container.addEventListener("click", e => {
    const selectBtn = e.target.closest(".row-select-btn");
    if (selectBtn) {
      showDetail(selectBtn.dataset.id);
    }
  });

  container.querySelector("#btn-detail-close").addEventListener("click", () => {
    detailPanel.style.display = "none";
    selectedRowId = null;
  });

  container.querySelector("#btn-detail-view").addEventListener("click", () => {
    if (selectedRowId) {
      window.showScreen("scr-1781413282852");
    }
  });

  // フィルター入力のEnterキー対応
  container.querySelector("#filter-order-id").addEventListener("keypress", e => {
    if (e.key === "Enter") applyFilters();
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス
  const PRIORITY_TABLE = 0;
  const VALIDATION_TABLE = 1;
  const DUPLICATE_TABLE = 2;
  const CHANNEL_CONFLICT_TABLE = 3;
  const MISSING_TABLE = 4;
  const OCR_TABLE = 5;

  let allRows = [];
  let currentTab = "all";
  let selectedRowId = null;

  // 1. 再描画関数
  function renderPriorityList(rows) {
    const tbody = container.querySelector("#priority-tbody");
    tbody.innerHTML = rows.map(r => {
      const severityColor = r.重要度 === "致命的" ? "#ff6b6b" : r.重要度 === "高" ? "#ffc107" : r.重要度 === "中" ? "#2196f3" : "#9fb0d1";
      const statusBg = r.修正ステータス === "完了" ? "rgba(76,175,80,0.2)" : r.修正ステータス === "対応中" ? "rgba(255,193,7,0.2)" : "rgba(158,176,209,0.2)";
      return `
        <tr data-id="${r.優先度リストID}" style="border-bottom: 1px solid rgba(255,255,255,0.08); cursor: pointer; transition: background 0.2s;">
          <td style="padding: 8px; color: var(--text); font-weight: 600;">${r.優先度レベル || "-"}</td>
          <td style="padding: 8px; color: var(--text); font-family: monospace; font-size: 11px;">${(r.受注データID || "").substring(0, 8)}</td>
          <td style="padding: 8px; color: var(--text); font-size: 11px;">${r.エラー分類 || "-"}</td>
          <td style="padding: 8px; color: ${severityColor}; font-weight: 500;">${r.重要度 || "-"}</td>
          <td style="padding: 8px; text-align: center; color: var(--text);">${r.信頼度スコア || 0}</td>
          <td style="padding: 8px; background: ${statusBg}; border-radius: 3px; color: var(--text); font-size: 11px;">${r.修正ステータス || "-"}</td>
          <td style="padding: 8px; color: var(--text-muted); font-size: 11px;">${r.割り当て先ユーザーID ? "割当済" : "-"}</td>
          <td style="padding: 8px; text-align: center;">
            <button class="action-btn secondary detail-btn" data-id="${r.優先度リストID}" style="padding: 4px 6px; font-size: 10px;">詳細</button>
          </td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(PRIORITY_TABLE);
    if (rows) {
      allRows = rows;
      updateKPIs();
      renderPriorityList(rows);
    }
  }

  // 3. KPI 更新
  function updateKPIs() {
    const validationRows = allRows;
    const failed = validationRows.filter(r => r.検証ステータス === "不合格").length;
    const warning = validationRows.filter(r => r.検証ステータス === "警告").length;
    const passed = validationRows.filter(r => r.検証ステータス === "合格").length;
    const pending = validationRows.filter(r => r.検証ステータス === "保留").length;

    container.querySelector("[data-testid='kpi-failed']").textContent = failed;
    container.querySelector("[data-testid='kpi-warning']").textContent = warning;
    container.querySelector("[data-testid='kpi-passed']").textContent = passed;
    container.querySelector("[data-testid='kpi-pending']").textContent = pending;
  }

  // 4. フィルタリング
  function applyFilters() {
    const statusFilter = container.querySelector("[data-testid='status-filter']").value;
    const channelFilter = container.querySelector("[data-testid='channel-filter']").value;
    const severityFilter = container.querySelector("[data-testid='severity-filter']").value;
    const confidenceMin = parseInt(container.querySelector("[data-testid='confidence-min']").value) || 0;

    let filtered = allRows;

    if (statusFilter) {
      filtered = filtered.filter(r => r.検証ステータス === statusFilter);
    }
    if (channelFilter) {
      filtered = filtered.filter(r => r.チャネル === channelFilter);
    }
    if (severityFilter) {
      filtered = filtered.filter(r => r.重要度 === severityFilter);
    }
    filtered = filtered.filter(r => (r.信頼度スコア || 0) >= confidenceMin);

    renderPriorityList(filtered);
  }

  // 5. 検索ボタン
  container.querySelector("[data-testid='search-button']").addEventListener("click", applyFilters);

  // 6. 詳細パネル表示
  function showDetail(rowId) {
    const row = allRows.find(r => r.優先度リストID === rowId);
    if (!row) return;

    selectedRowId = rowId;
    const detailPanel = container.querySelector("#detail-panel");
    const noSelection = container.querySelector("#no-selection");

    container.querySelector("#detail-item").textContent = row.検証項目 || "-";
    container.querySelector("#detail-error-code").textContent = row.エラーコード || "-";
    container.querySelector("#detail-error-msg").textContent = row.エラーメッセージ || "-";
    container.querySelector("#detail-actual").textContent = row.検証値 || "-";
    container.querySelector("#detail-expected").textContent = row.期待値 || "-";
    container.querySelector("#detail-status").value = row.対応状況 || "未対応";
    container.querySelector("#detail-notes").value = row.備考 || "";

    detailPanel.style.display = "block";
    noSelection.style.display = "none";
  }

  // 7. 詳細パネル保存
  container.querySelector("[data-testid='detail-save-button']").addEventListener("click", async () => {
    if (!selectedRowId) return;
    const status = container.querySelector("#detail-status").value;
    const notes = container.querySelector("#detail-notes").value;

    const updated = await window.aivicApi.update(PRIORITY_TABLE, selectedRowId, {
      対応状況: status,
      備考: notes
    });

    if (updated) {
      const rows = await window.aivicApi.list(PRIORITY_TABLE);
      if (rows) {
        allRows = rows;
        updateKPIs();
        renderPriorityList(rows);
        showDetail(selectedRowId);
      }
    }
  });

  // 8. 詳細パネル閉じる
  container.querySelector("[data-testid='detail-close-button']").addEventListener("click", () => {
    container.querySelector("#detail-panel").style.display = "none";
    container.querySelector("#no-selection").style.display = "block";
    selectedRowId = null;
  });

  // 9. 行クリックで詳細表示
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      showDetail(detailBtn.dataset.id);
    }
  });

  // 10. CSV エクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", () => {
    if (!allRows || allRows.length === 0) {
      alert("エクスポート対象がありません");
      return;
    }
    const headers = ["優先度レベル", "受注データID", "エラー分類", "重要度", "信頼度スコア", "修正ステータス", "割当先"];
    const csv = [
      "\uFEFF" + headers.map(h => `"${h}"`).join(","),
      ...allRows.map(r => [
        r.優先度レベル || "",
        r.受注データID || "",
        r.エラー分類 || "",
        r.重要度 || "",
        r.信頼度スコア || "",
        r.修正ステータス || "",
        r.割り当て先ユーザーID ? "割当済" : ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv;charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = "priority_list_" + new Date().toISOString().split("T")[0] + ".csv";
    link.click();
  });

  // 11. タブ切り替え（簡易版：全件表示のみ）
  container.querySelector("[data-testid='tab-all']").addEventListener("click", () => {
    currentTab = "all";
    renderPriorityList(allRows);
  });

  // 12. 初期化
  loadInitialData();
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#confidence-tbody");
  const detailPanel = container.querySelector("#detail-panel");
  const detailEmpty = container.querySelector("#detail-empty");
  const detailHeader = container.querySelector("#detail-header");

  let allRows = [];
  let selectedRowId = null;

  // 1. 信頼度ゲージ描画関数
  function drawConfidenceGauge(score) {
    const canvas = container.querySelector("#confidence-gauge");
    if (!canvas) return;
    const ctx = canvas.getContext("2d");
    const w = canvas.width;
    const h = canvas.height;

    ctx.clearRect(0, 0, w, h);

    // 背景ゲージ
    ctx.fillStyle = "rgba(255,255,255,0.1)";
    ctx.fillRect(20, h - 30, w - 40, 20);

    // スコアゲージ
    const ratio = Math.max(0, Math.min(100, score)) / 100;
    let gaugeColor = "#ff4444"; // 赤
    if (ratio > 0.75) gaugeColor = "#44ff44"; // 緑
    else if (ratio > 0.5) gaugeColor = "#ffaa00"; // 橙

    ctx.fillStyle = gaugeColor;
    ctx.fillRect(20, h - 30, (w - 40) * ratio, 20);

    // スコアテキスト
    ctx.fillStyle = "#ffd700";
    ctx.font = "bold 18px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText(Math.round(score), w / 2, 25);
  }

  // 2. 再描画関数
  function renderRows(rows) {
    allRows = rows;
    tbody.innerHTML = rows.map(r => {
      const score = r.総合スコア || r.overall_confidence || 0;
      const warning = r.警告レベル || r.warning_level || "—";
      const orderId = r.受注データID || r.order_id || r.id || "—";

      let scoreColor = "#ff4444";
      if (score >= 76) scoreColor = "#44ff44";
      else if (score >= 51) scoreColor = "#ffaa00";

      return `
        <tr data-id="${r.id}" style="border-bottom: 1px solid var(--border); cursor: pointer; transition: background 0.15s;">
          <td style="padding: 8px 10px; color: var(--text); border-right: 1px solid var(--border); word-break: break-word;">${orderId}</td>
          <td style="padding: 8px 10px; text-align: center; color: ${scoreColor}; font-weight: 600; border-right: 1px solid var(--border);">${score}</td>
          <td style="padding: 8px 10px; text-align: center; color: var(--text);">${warning}</td>
        </tr>
      `;
    }).join("");

    // 行クリックイベント
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.addEventListener("click", () => selectRow(tr.dataset.id));
      tr.addEventListener("mouseover", () => tr.style.background = "rgba(255,215,0,0.05)");
      tr.addEventListener("mouseout", () => tr.style.background = "");
    });
  }

  // 3. 行選択と詳細表示
  function selectRow(rowId) {
    selectedRowId = rowId;
    const row = allRows.find(r => r.id === rowId);
    if (!row) return;

    // ハイライト
    tbody.querySelectorAll("tr").forEach(tr => {
      tr.style.background = tr.dataset.id === rowId ? "rgba(255,215,0,0.1)" : "";
    });

    // 詳細表示
    detailEmpty.style.display = "none";
    detailPanel.style.display = "block";

    const orderId = row.受注データID || row.order_id || row.id;
    detailHeader.innerHTML = `<span style="color: var(--text); font-weight: 600;">受注ID: ${orderId}</span>`;

    // スコア情報
    const overallScore = row.総合スコア || row.overall_confidence || 0;
    container.querySelector("#detail-overall-score").textContent = overallScore;
    container.querySelector("#detail-warning-level").textContent = row.警告レベル || row.warning_level || "—";
    container.querySelector("#detail-completeness").textContent = (row.完全性スコア || row.completeness_score || 0) + "%";
    container.querySelector("#detail-accuracy").textContent = (row.正確性スコア || row.accuracy_score || 0) + "%";
    container.querySelector("#detail-consistency").textContent = (row.一貫性スコア || row.consistency_score || 0) + "%";

    // ゲージ描画
    drawConfidenceGauge(overallScore);

    // 修正前後比較
    const beforeValue = row.検証値 || row.validation_value || row.raw_ocr_text || "（データなし）";
    container.querySelector("#detail-before-value").textContent = beforeValue;
    container.querySelector("#detail-after-value").textContent = "（未修正）";

    // フォームリセット
    container.querySelector("#input-corrected-value").value = "";
    container.querySelector("#select-correction-reason").value = "";
    container.querySelector("#input-correction-comment").value = "";
    container.querySelector("#flag-requires-correction").checked = row.警告フラグ || row.warning_flag || false;
  }

  // 4. フィルタ・ソート関数
  function applyFiltersAndSort() {
    let filtered = [...allRows];

    const orderId = container.querySelector("#search-order-id").value.toLowerCase();
    const scoreRange = container.querySelector("#filter-score-range").value;
    const warningLevel = container.querySelector("#filter-warning-level").value;
    const sortBy = container.querySelector("#sort-by").value;

    // フィルタ
    if (orderId) {
      filtered = filtered.filter(r => {
        const id = (r.受注データID || r.order_id || r.id || "").toLowerCase();
        return id.includes(orderId);
      });
    }

    if (scoreRange) {
      const [min, max] = scoreRange.split("-").map(Number);
      filtered = filtered.filter(r => {
        const score = r.総合スコア || r.overall_confidence || 0;
        return score >= min && score <= max;
      });
    }

    if (warningLevel) {
      filtered = filtered.filter(r => (r.警告レベル || r.warning_level || "") === warningLevel);
    }

    // ソート
    if (sortBy === "score-asc") {
      filtered.sort((a, b) => (a.総合スコア || a.overall_confidence || 0) - (b.総合スコア || b.overall_confidence || 0));
    } else if (sortBy === "score-desc") {
      filtered.sort((a, b) => (b.総合スコア || b.overall_confidence || 0) - (a.総合スコア || a.overall_confidence || 0));
    } else if (sortBy === "date-new") {
      filtered.sort((a, b) => new Date(b.スコア計算日時 || b.created_at || 0) - new Date(a.スコア計算日時 || a.created_at || 0));
    } else if (sortBy === "date-old") {
      filtered.sort((a, b) => new Date(a.スコア計算日時 || a.created_at || 0) - new Date(b.スコア計算日時 || b.created_at || 0));
    }

    renderRows(filtered);
  }

  // 5. 初期データ読み込み
  if (tables[0] && tables[0].records) {
    renderRows(tables[0].records);
  } else {
    window.aivicApi.list(0).then(rows => {
      if (rows) renderRows(rows);
    });
  }

  // 6. フィルタ・ソートイベント
  container.querySelector("#search-order-id").addEventListener("input", applyFiltersAndSort);
  container.querySelector("#filter-score-range").addEventListener("change", applyFiltersAndSort);
  container.querySelector("#filter-warning-level").addEventListener("change", applyFiltersAndSort);
  container.querySelector("#sort-by").addEventListener("change", applyFiltersAndSort);

  // 7. 修正保存ボタン
  container.querySelector("#btn-save-correction").addEventListener("click", async () => {
    if (!selectedRowId) {
      alert("行を選択してください");
      return;
    }

    const correctedValue = container.querySelector("#input-corrected-value").value.trim();
    const reason = container.querySelector("#select-correction-reason").value;
    const comment = container.querySelector("#input-correction-comment").value.trim();

    if (!correctedValue) {
      alert("修正値を入力してください");
      return;
    }
    if (!reason) {
      alert("修正理由を選択してください");
      return;
    }

    const row = allRows.find(r => r.id === selectedRowId);
    const beforeValue = row.検証値 || row.validation_value || row.raw_ocr_text || "";

    // 修正履歴を保存（テーブルインデックス 1 を想定）
    const correctionRecord = {
      受注データID: row.受注データID || row.order_id || row.id,
      修正項目名: row.検証項目 || row.validation_item || "OCR読み込み値",
      修正前値: beforeValue,
      修正後値: correctedValue,
      修正理由: reason,
      修正備考: comment,
      修正ユーザーID: "current-user-id",
      修正日時: new Date().toISOString()
    };

    const saved = await window.aivicApi.save(1, correctionRecord);
    if (saved) {
      alert("修正を保存しました");
      container.querySelector("#input-corrected-value").value = "";
      container.querySelector("#select-correction-reason").value = "";
      container.querySelector("#input-correction-comment").value = "";
      container.querySelector("#detail-after-value").textContent = correctedValue;
    }
  });

  // 8. キャンセルボタン
  container.querySelector("#btn-cancel-correction").addEventListener("click", () => {
    container.querySelector("#input-corrected-value").value = "";
    container.querySelector("#select-correction-reason").value = "";
    container.querySelector("#input-correction-comment").value = "";
  });
}

function(container, apiUrl, tables) {
  // テーブルインデックス: 信頼度スコア = 0
  const scoreTableIndex = 0;

  // 1. 再描画関数
  function renderRows(rows) {
    const tbody = container.querySelector("#results-tbody");
    if (!rows || rows.length === 0) {
      tbody.innerHTML = '<tr style="border-bottom: 1px solid var(--border);"><td colspan="9" style="padding: 1rem; text-align: center; color: var(--text-muted);">該当データなし</td></tr>';
      container.querySelector("#result-count").textContent = "0";
      return;
    }

    tbody.innerHTML = rows.map(r => {
      const warningBadge = r.警告フラグ ? '<span style="background: #c41e3a; color: #fff; padding: 0.25rem 0.5rem; border-radius: 3px; font-size: 0.75rem; font-weight: 600;">⚠</span>' : '-';
      return `<tr data-id="${r.信頼度スコアID || r.id}" style="border-bottom: 1px solid var(--border); hover: background: var(--bg-main);">
        <td style="padding: 0.5rem; color: var(--text);">${(r.受注データID || '').substring(0, 8)}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text); font-weight: 600;">${r.総合スコア || '-'}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text);">${r.完全性スコア || '-'}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text);">${r.正確性スコア || '-'}</td>
        <td style="padding: 0.5rem; text-align: center; color: var(--text);">${r.一貫性スコア || '-'}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.チャネル || '-'}</td>
        <td style="padding: 0.5rem; color: var(--text);">${r.検証ステータス || '-'}</td>
        <td style="padding: 0.5rem; text-align: center;">${warningBadge}</td>
        <td style="padding: 0.5rem; text-align: center;">
          <button class="action-btn secondary detail-btn" data-id="${r.信頼度スコアID || r.id}" style="padding: 0.25rem 0.5rem; font-size: 0.75rem;">詳細</button>
        </td>
      </tr>`;
    }).join("");

    container.querySelector("#result-count").textContent = rows.length;
  }

  // 2. KPI 更新関数
  function updateKPIs(rows) {
    if (!rows || rows.length === 0) {
      container.querySelector("[data-testid='kpi-avg-score']").textContent = "--";
      container.querySelector("[data-testid='kpi-warning-count']").textContent = "0";
      container.querySelector("[data-testid='kpi-total-count']").textContent = "0";
      return;
    }

    const avgScore = Math.round(rows.reduce((sum, r) => sum + (r.総合スコア || 0), 0) / rows.length);
    const warningCount = rows.filter(r => r.警告フラグ).length;

    container.querySelector("[data-testid='kpi-avg-score']").textContent = avgScore;
    container.querySelector("[data-testid='kpi-warning-count']").textContent = warningCount;
    container.querySelector("[data-testid='kpi-total-count']").textContent = rows.length;
  }

  // 3. スコア分布グラフ描画
  function drawScoreDistribution(rows) {
    const canvas = container.querySelector("#score-distribution-chart");
    if (!canvas) return;

    const ctx = canvas.getContext("2d");
    const rect = canvas.getBoundingClientRect();
    canvas.width = rect.width;
    canvas.height = rect.height;

    // スコアを 10 段階にビン化
    const bins = Array(10).fill(0);
    (rows || []).forEach(r => {
      const score = r.総合スコア || 0;
      const binIndex = Math.min(Math.floor(score / 10), 9);
      bins[binIndex]++;
    });

    const maxBin = Math.max(...bins, 1);
    const barWidth = canvas.width / 10;
    const padding = 30;
    const graphHeight = canvas.height - padding * 2;

    // 背景
    ctx.fillStyle = "#1a2a40";
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    // グリッド
    ctx.strokeStyle = "rgba(255,255,255,0.1)";
    ctx.lineWidth = 1;
    for (let i = 0; i <= 5; i++) {
      const y = padding + (graphHeight / 5) * i;
      ctx.beginPath();
      ctx.moveTo(padding, y);
      ctx.lineTo(canvas.width - padding, y);
      ctx.stroke();
    }

    // バー描画
    bins.forEach((count, i) => {
      const barHeight = (count / maxBin) * graphHeight;
      const x = padding + i * barWidth + barWidth * 0.1;
      const y = canvas.height - padding - barHeight;

      ctx.fillStyle = "#d4a574";
      ctx.fillRect(x, y, barWidth * 0.8, barHeight);

      // ラベル
      ctx.fillStyle = "#9fb0d1";
      ctx.font = "11px sans-serif";
      ctx.textAlign = "center";
      ctx.fillText(`${i * 10}-${(i + 1) * 10}`, x + barWidth * 0.4, canvas.height - padding + 15);
      ctx.fillText(count, x + barWidth * 0.4, y - 5);
    });

    // 軸ラベル
    ctx.fillStyle = "#9fb0d1";
    ctx.font = "12px sans-serif";
    ctx.textAlign = "center";
    ctx.fillText("スコア", canvas.width / 2, canvas.height - 5);
    ctx.save();
    ctx.translate(10, canvas.height / 2);
    ctx.rotate(-Math.PI / 2);
    ctx.fillText("件数", 0, 0);
    ctx.restore();
  }

  // 4. フィルタ適用関数
  async function applyFilters() {
    const allRows = await window.aivicApi.list(scoreTableIndex);
    if (!allRows) return;

    const minScore = parseInt(container.querySelector("#score-min-slider").value);
    const maxScore = parseInt(container.querySelector("#score-max-slider").value);
    const channel = container.querySelector("#channel-filter").value;
    const validationStatus = container.querySelector("#validation-status-filter").value;
    const hasCorrectionHistory = container.querySelector("#has-correction-history").checked;
    const duplicateFlag = container.querySelector("#duplicate-flag").checked;
    const channelConflictFlag = container.querySelector("#channel-conflict-flag").checked;
    const missingInputFlag = container.querySelector("#missing-input-flag").checked;
    const ocrLowConfidence = container.querySelector("#ocr-low-confidence").checked;
    const voiceMismatch = container.querySelector("#voice-mismatch").checked;

    const filtered = allRows.filter(r => {
      const score = r.総合スコア || 0;
      if (score < minScore || score > maxScore) return false;
      if (channel && r.チャネル !== channel) return false;
      if (validationStatus && r.検証ステータス !== validationStatus) return false;
      if (hasCorrectionHistory && !r.修正履歴有無) return false;
      if (duplicateFlag && !r.重複検出フラグ) return false;
      if (channelConflictFlag && !r.チャネル間矛盾フラグ) return false;
      if (missingInputFlag && !r.入力漏れ検出フラグ) return false;
      if (ocrLowConfidence && !r.AI_OCR低信頼度) return false;
      if (voiceMismatch && !r.音声ガイダンス不一致) return false;
      return true;
    });

    renderRows(filtered);
    updateKPIs(filtered);
    drawScoreDistribution(filtered);
  }

  // 5. 初期データ読み込み
  window.aivicApi.list(scoreTableIndex).then(rows => {
    renderRows(rows || []);
    updateKPIs(rows || []);
    drawScoreDistribution(rows || []);
  });

  // 6. スライダー連動表示
  container.querySelector("#score-min-slider").addEventListener("input", e => {
    container.querySelector("#score-min-display").textContent = e.target.value;
  });
  container.querySelector("#score-max-slider").addEventListener("input", e => {
    container.querySelector("#score-max-display").textContent = e.target.value;
  });

  // 7. フィルタボタン
  container.querySelector("#btn-apply-filters").addEventListener("click", applyFilters);

  container.querySelector("#btn-reset-filters").addEventListener("click", () => {
    container.querySelector("#score-min-slider").value = 0;
    container.querySelector("#score-max-slider").value = 100;
    container.querySelector("#score-min-display").textContent = "0";
    container.querySelector("#score-max-display").textContent = "100";
    container.querySelector("#channel-filter").value = "";
    container.querySelector("#validation-status-filter").value = "";
    container.querySelector("#has-correction-history").checked = false;
    container.querySelector("#duplicate-flag").checked = false;
    container.querySelector("#channel-conflict-flag").checked = false;
    container.querySelector("#missing-input-flag").checked = false;
    container.querySelector("#ocr-low-confidence").checked = false;
    container.querySelector("#voice-mismatch").checked = false;
    applyFilters();
  });

  // 8. CSV エクスポート
  container.querySelector("[data-testid='export-csv-button']").addEventListener("click", async () => {
    const rows = await window.aivicApi.list(scoreTableIndex);
    if (!rows || rows.length === 0) {
      alert("エクスポートするデータがありません");
      return;
    }

    const headers = ["受注データID", "総合スコア", "完全性スコア", "正確性スコア", "一貫性スコア", "チャネル", "検証ステータス", "警告フラグ", "スコア計算日時"];
    const csv = [
      "\uFEFF" + headers.join(","),
      ...rows.map(r => [
        r.受注データID || "",
        r.総合スコア || "",
        r.完全性スコア || "",
        r.正確性スコア || "",
        r.一貫性スコア || "",
        r.チャネル || "",
        r.検証ステータス || "",
        r.警告フラグ ? "○" : "",
        r.スコア計算日時 || ""
      ].map(v => `"${String(v).replace(/"/g, '""')}"`).join(","))
    ].join("\n");

    const blob = new Blob([csv], { type: "text/csv; charset=utf-8;" });
    const link = document.createElement("a");
    link.href = URL.createObjectURL(blob);
    link.download = `score-filter-${new Date().toISOString().split("T")[0]}.csv`;
    link.click();
  });

  // 9. 詳細ボタン
  container.addEventListener("click", e => {
    const detailBtn = e.target.closest(".detail-btn");
    if (detailBtn) {
      const id = detailBtn.dataset.id;
      window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
    }
  });
}

function(container, apiUrl, tables) {
  const tbody = container.querySelector("#records-tbody");
  const selectAllCheckbox = container.querySelector("#select-all");
  const searchBtn = container.querySelector("#btn-search");
  const batchRevalidateBtn = container.querySelector("#btn-batch-revalidate");
  const individualRevalidateBtn = container.querySelector("#btn-individual-revalidate");
  const viewDetailBtn = container.querySelector("#btn-view-detail");
  const processingStatus = container.querySelector("#processing-status");
  const progressBar = container.querySelector("#progress-bar");
  const resultSummary = container.querySelector("#result-summary");

  let allRecords = [];
  let selectedIds = new Set();

  // 1. 再描画関数
  function renderRows(rows) {
    tbody.innerHTML = rows.map(r => {
      const status = r.検証ステータス || "保留";
      const score = r.総合スコア || 0;
      const priority = r.優先度レベル || 3;
      const lastValidated = r.検証実行日時 ? new Date(r.検証実行日時).toLocaleString('ja-JP', { year: 'numeric', month: '2-digit', day: '2-digit', hour: '2-digit', minute: '2-digit' }) : "-";

      const statusColor = status === "合格" ? "#4ade80" : status === "不合格" ? "#ef4444" : status === "警告" ? "#f59e0b" : "#6b7280";

      return `
        <tr data-id="${r.検証結果ID || r.id}" style="border-bottom: 1px solid var(--border); hover-background: rgba(255,255,255,0.02);">
          <td style="padding: 8px 12px; border-right: 1px solid var(--border);">
            <input type="checkbox" class="row-checkbox" data-id="${r.検証結果ID || r.id}" style="cursor: pointer; accent-color: var(--primary);" />
          </td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text); font-weight: 500;">${r.受注データID || "-"}</td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); color: var(--text);">${r.チャネルコード || "-"}</td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border);">
            <span style="display: inline-block; padding: 2px 6px; border-radius: 3px; background: ${statusColor}20; color: ${statusColor}; font-size: 11px; font-weight: 600;">${status}</span>
          </td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center; color: var(--text); font-weight: 600;">${score}</td>
          <td style="padding: 8px 12px; border-right: 1px solid var(--border); text-align: center; color: var(--text);">P${priority}</td>
          <td style="padding: 8px 12px; color: var(--text-muted); font-size: 11px;">${lastValidated}</td>
        </tr>
      `;
    }).join("");
  }

  // 2. 初期データ読み込み
  async function loadInitialData() {
    const rows = await window.aivicApi.list(0);
    if (rows) {
      allRecords = rows;
      renderRows(rows);
    }
  }

  // 3. 検索処理
  searchBtn.addEventListener("click", async () => {
    const orderId = container.querySelector("#search-order-id").value.trim();
    const channel = container.querySelector("#filter-channel").value;
    const status = container.querySelector("#filter-status").value;

    let filtered = allRecords;
    if (orderId) {
      filtered = filtered.filter(r => (r.受注データID || "").includes(orderId));
    }
    if (channel) {
      filtered = filtered.filter(r => r.チャネルコード === channel);
    }
    if (status) {
      filtered = filtered.filter(r => r.検証ステータス === status);
    }

    renderRows(filtered);
  });

  // 4. チェックボックス処理
  selectAllCheckbox.addEventListener("change", (e) => {
    const checkboxes = container.querySelectorAll(".row-checkbox");
    checkboxes.forEach(cb => {
      cb.checked = e.target.checked;
      if (e.target.checked) {
        selectedIds.add(cb.dataset.id);
      } else {
        selectedIds.delete(cb.dataset.id);
      }
    });
  });

  container.addEventListener("change", (e) => {
    if (e.target.classList.contains("row-checkbox")) {
      if (e.target.checked) {
        selectedIds.add(e.target.dataset.id);
      } else {
        selectedIds.delete(e.target.dataset.id);
      }
      updateSelectAllCheckbox();
    }
  });

  function updateSelectAllCheckbox() {
    const checkboxes = container.querySelectorAll(".row-checkbox");
    const allChecked = Array.from(checkboxes).every(cb => cb.checked);
    const someChecked = Array.from(checkboxes).some(cb => cb.checked);
    selectAllCheckbox.checked = allChecked;
    selectAllCheckbox.indeterminate = someChecked && !allChecked;
  }

  // 5. 一括再検証実行
  batchRevalidateBtn.addEventListener("click", async () => {
    if (selectedIds.size === 0) {
      alert("再検証対象を選択してください");
      return;
    }

    const rules = {
      duplicate: container.querySelector("#rule-duplicate").checked,
      channelConflict: container.querySelector("#rule-channel-conflict").checked,
      missingInput: container.querySelector("#rule-missing-input").checked,
      ocrConfidence: container.querySelector("#rule-ocr-confidence").checked
    };

    processingStatus.style.display = "block";
    progressBar.style.width = "0%";
    resultSummary.innerHTML = '<div style="padding: 8px; background: rgba(0,0,0,0.2); border-radius: 4px; color: var(--text-muted);">処理中...</div>';

    try {
      let processed = 0;
      const total = selectedIds.size;
      const results = { success: 0, failed: 0, warnings: 0 };

      for (const id of selectedIds) {
        // シミュレーション: 実際の API 呼び出しに置き換える
        await new Promise(resolve => setTimeout(resolve, 200));

        processed++;
        progressBar.style.width = (processed / total * 100) + "%";

        // ランダムに結果を生成（デモ用）
        const rand = Math.random();
        if (rand > 0.8) results.failed++;
        else if (rand > 0.6) results.warnings++;
        else results.success++;
      }

      resultSummary.innerHTML = `
        <div style="display: flex; flex-direction: column; gap: 6px;">
          <div style="padding: 8px; background: rgba(74, 222, 128, 0.1); border-radius: 4px; color: #4ade80; font-size: 11px;">
            ✓ 成功: ${results.success}件
          </div>
          <div style="padding: 8px; background: rgba(245, 158, 11, 0.1); border-radius: 4px; color: #f59e0b; font-size: 11px;">
            ⚠ 警告: ${results.warnings}件
          </div>
          <div style="padding: 8px; background: rgba(239, 68, 68, 0.1); border-radius: 4px; color: #ef4444; font-size: 11px;">
            ✗ 失敗: ${results.failed}件
          </div>
        </div>
      `;

      setTimeout(() => {
        processingStatus.style.display = "none";
        loadInitialData();
      }, 1000);
    } catch (err) {
      resultSummary.innerHTML = `<div style="padding: 8px; background: rgba(239, 68, 68, 0.1); border-radius: 4px; color: #ef4444; font-size: 11px;">エラーが発生しました</div>`;
      processingStatus.style.display = "none";
    }
  });

  // 6. 個別再検証
  individualRevalidateBtn.addEventListener("click", () => {
    if (selectedIds.size === 0) {
      alert("再検証対象を選択してください");
      return;
    }
    if (selectedIds.size > 1) {
      alert("1件のみ選択してください");
      return;
    }
    const id = Array.from(selectedIds)[0];
    window.showScreen("scr-1781413282852"); // 受注データ詳細確認・修正画面
  });

  // 7. 詳細確認
  viewDetailBtn.addEventListener("click", () => {
    if (selectedIds.size === 0) {
      alert("対象を選択してください");
      return;
    }
    window.showScreen("scr-1781413382983"); // 受注データ検証結果レポート画面
  });

  // 初期化
  loadInitialData();
}
